Object.assign(quranData, {
    8: { // سورة الأنفال
        name: "الأنفال",
        basmalaTafsir: ``,
        verses: [
            { text: "يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `يا رسول الله ( عَنِ الْأَنْفالِ ) هو جمع « نفل » بمعنى الزيادة ، والمراد هنا : الغنيمة ، وإنما سميت نفلا لأنها عطية وفضل من الله سبحانه للمسلمين ، وقد اختلف التفسير حول الأنفال ، والذي نعتقده بعد الجمع بين الآيات والروايات أن الأشياء التي ليست ملكا لأحد وغنائم دار الحرب تنقسم إلى قسمين : الأول : الغنائم ؛ وهي تقسم إلى خمسة أقسام : قسم يسمى « الخمس » لله والرسول ولذي القربى واليتامى والمساكين وابن السبيل. والأربعة الباقية للمقاتلين. الثاني : الأنفال ؛ وهي ما سيأتي في الرواية ، وتكون لله والرسول صلى‌الله‌عليه‌وآله‌وسلم والإمام ، وقد أبيحت في حال الغيبة لمن يتولى الأئمة عليهم‌السلام ، أو لمطلق من حازها مؤمنا كان أو غير مؤمن. وظاهر سياق الآية أن المراد بالأنفال هنا هي مطلق الغنائم ، فإن السورة نزلت في وقعة بدر ، ولما هزم المسلمون الكفار ، انقسموا ثلاث فرق. روى عبادة بن الصامت قال : خرجنا مع رسول الله صلى‌الله‌عليه‌وآله‌وسلم فشهدت معه بدرا فهزم الله تعالى العدو فانطلقت طائفة في آثارهم يهزمون ويقتلون ، وأقبلت طائفة على العسكر يحوزونه ويجمعونه وأحدقت طائفة برسول الله صلى‌الله‌عليه‌وآله‌وسلم لا يصيب العدو منه غرّة ، حتى إذا كان الليل وفاء الناس بعضهم إلى بعض ، قال الذين جمعوا الغنائم : نحن حويناها فليس لأحد فيها نصيب. وقال الذين خرجوا في طلب العدو : لستم بأحق منا نحن منعنا عنه العدو وهزمناهم. وقال الذين أحدقوا برسول الله صلى‌الله‌عليه‌وآله‌وسلم : خفنا أن يصيب العدو منه غرّة فاشتغلنا به. فنزلت الآية : ( يَسْئَلُونَكَ عَنِ الْأَنْفالِ ) ؟ ( قُلِ الْأَنْفالُ لِلَّهِ وَالرَّسُولِ فَاتَّقُوا اللهَ وَأَصْلِحُوا ذاتَ بَيْنِكُمْ ) فقسمها رسول الله صلى‌الله‌عليه‌وآله‌وسلم بين المسلمين. وهذا الحديث يدل على أن المراد بالأنفال مطلق الغنائم ، كما هو ظاهر السياق ، وهناك حديث يفسر الأنفال بما يحضر الإمام بعد الرسول صلى‌الله‌عليه‌وآله‌وسلم ، ولا منافاة بين الأمرين ، فقد تكرر منا سابقا أن اللفظ المشترك يجوز استعماله في أكثر من معنى واحد إذا كانت هناك قرينة. فعن الإمام الصادق عليه‌السلام أنه قال : « الأنفال ما لم يوجف عليه بخيل ولا ركاب أو قوم صالحوا وأعطوا بيدهم » (1) . و في حديث آخر عنه عليه‌السلام : « الفيء والأنفال ما كان من أرض خربة أو بطون أودية أو أرض لم يكن فيها مهراقة دم أو صولحوا أو أعطوا بأيديهم ولم تفتح بالسيف فهو يكون من الفيء والأنفال ، فهذه لله ورسوله فما كان لله فهو لرسوله يضعه حيث يشاء وهو للإمام بعد الرسول » (2) . و في حديث آخر عنه عليه‌السلام : « الأنفال كل ما أخذ من دار الحرب بغير قتال ، وكل أرض انجلى عنها أهلها بغير قتال والأرضون الموات والآجام وبطون الأودية وقطائع الملوك وميراث من لا وارث له فهو لله ولرسوله ولو من قام بنصه ومن مات وليس له مولى فماله من الأنفال » (3) . ( 1) الكافي : ج 1 ص 539. ( 2) وسائل الشيعة : ج 9 ص 527. ( 3) بحار الأنوار : ج 19 ص 210. قُلِ الأَنفَالُ لِلّهِ وَالرَّسُولِ فَاتَّقُواْ اللّهَ وَأَصْلِحُواْ ذَاتَ بِيْنِكُمْ وَأَطِيعُواْ اللّهَ وَرَسُولَهُ إِن كُنتُم مُّؤْمِنِينَ (1) إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا وعلى هذا فتسمية هذا الشيء بالأنفال لزيادة الإمام بحصة دون سائر شركائه في الخمس. ( قُلِ ) يا رسول الله في جواب السائلين عن الأنفال : ( الْأَنْفالُ لِلَّهِ وَالرَّسُولِ ) ليس لأحد حتى يتنازع فيها ، وإذا كانت لله والرسول فلهما الخيار في أن يقسماها كيف شاءا ( فَاتَّقُوا اللهَ ) خافوا عقابه في التنازع وطلب ما ليس لكم ( وَأَصْلِحُوا ذاتَ بَيْنِكُمْ ) أي ما بينكم من الخصومة والمنازعة ، وإنما يؤتى بكلمة « ذات » لتشبيه الصلة التي بين الناس بأمر مجسّم فيما بينهم ، تشبيها للمعقول بالمحسوس ( وَأَطِيعُوا اللهَ وَرَسُولَهُ ) في الغنائم وغيرها ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) مصدقين للرسول فيما يأتيكم به من قبل الله سبحانه. قيل : إنه لما عرف المسلمين أنه لا حق لهم في الغنيمة وأنها لله والرسول ، قالوا : يا رسول الله سمعا وطاعة فاصنع ما شئت. [3] ثم ذكر سبحانه صفات المؤمنين الكاملين ليكون درسا للمسلمين في مستقبل حياتهم وليكون ميزانا يزن المسلم نفسه فيه فقال : ( إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذا ذُكِرَ اللهُ وَجِلَتْ قُلُوبُهُمْ ) أي اضطربت وخافت من عظمته ، وإن لم يكن خوفا من ذنب ، فإن الإنسان إذا علم أنه سيحضر محضرا كبيرا وعظيما ارتجف قلبه خوفا من الفشل ( وَإِذا تُلِيَتْ ) أي قرأت ( عَلَيْهِمْ آياتُهُ زادَتْهُمْ ) الآيات ( إِيماناً ) فإن الإيمان ملكة في وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ (2) الَّذِينَ يُقِيمُونَ الصَّلاَةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ (3) أُوْلَـئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا لَّهُمْ دَرَجَاتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ (4) كَمَا أَخْرَجَكَ رَبُّكَ مِن بَيْتِكَ بِالْحَقِّ وَإِنَّ فَرِيقاً مِّنَ القلب ، كلما كرّر المطلب على الإنسان زادت الملكة قوة وثباتا ( وَعَلى رَبِّهِمْ يَتَوَكَّلُونَ ) في أمرهم ، فيفوّضون أمورهم إليه ، في كل مرجو ومخوف.` },
            { text: "إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ", tafsir: `` },
            { text: "ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ", tafsir: `بالإتيان بها مواظبين عليها ، والحث عليها بالنسبة إلى سائر الناس ، فإن الإقامة غير الإتيان ( وَمِمَّا رَزَقْناهُمْ يُنْفِقُونَ ) سواء الواجب من الإنفاق أو غيره.` },
            { text: "أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ", tafsir: `المتصفون بهذه الصفات ( هُمُ الْمُؤْمِنُونَ حَقًّا ) فهم الذين آمنوا بالله ورسوله ، وهم الذين شعرت قلوبهم الإيمان وامتثلت جوارحهم لتطبيقه ( لَهُمْ دَرَجاتٌ ) رفيعة ( عِنْدَ رَبِّهِمْ ) فهم مكتوبون عنده أصحاب الدرجات الرفيعة ، وسينالونها في الآخرة ( وَمَغْفِرَةٌ ) لذنوبهم ( وَرِزْقٌ كَرِيمٌ ) فهم يرزقون بإكرام وإعظام لا بإهانة وإذلال. [6] إن الأنفال لله والرسول ، وإن كره المسلمون ذلك ، فإن في كونها لله والرسول حسن العاقبة والمصير ، كما إن إخراجك يا رسول الله لوقعة بدر كان بالحق ولعاقبة حسنة ، وإن كره المسلمون ذلك ، فإن الله وحده يعلم العواقب ، ويأمر بما هو خير ( كَما أَخْرَجَكَ رَبُّكَ ) يا رسول الله ( مِنْ بَيْتِكَ بِالْحَقِ ) والمراد ب « البيت » هنا محل الإقامة ، وهي المدينة المنورة ، ومعنى « الإخراج » أمره بذلك ( وَ ) الحال ( إِنَّ فَرِيقاً مِنَ الْمُؤْمِنِينَ لَكارِهُونَ (5) الْمُؤْمِنِينَ لَكارِهُونَ ) للخروج. وقصة بدر في الجملة هي إن الكفار في مكة لما شرّدوا قسما من المسلمين إلى الحبشة ، وطاردوا الرسول وأصحابه ، حتى اضطروا للهجرة تحت جنح الظلام ، أخذوا بعد ذلك يؤذون المسلمين الباقين في مكة ، ويشيعون حول النبي صلى‌الله‌عليه‌وآله‌وسلم وأصحابه مختلف الإشاعات ، فأراد النبي صلى‌الله‌عليه‌وآله‌وسلم أن يضع حدا لهذه التعديات التي لا مبرر لها إلّا الحقد والحسد. وأخيرا عزم على قطع طريق تجارتهم التي تسير بين مكة والشام ، ليتأدبوا ويأخذوا بذلك حذرهم. فخرجت عير لقريش إلى الشام فيها كثرة وافرة من أموالهم ، فأمر الرسول صلى‌الله‌عليه‌وآله‌وسلم أصحابه بالخروج ليأخذوها ، وأخبرهم أن الله قد وعده إحدى الطائفتين ؛ غنيمة العير ، أو مطاردة قريش ومحاربتها وتبديدها ، فخرج هو صلى‌الله‌عليه‌وآله‌وسلم في ثلاثمائة وثلاثة عشر رجلا ، فلما قارب « بدر » وهي بئر هناك أبلغ أبا سفيان ذلك ، وكان في العير فخاف خوفا شديدا ، وبعث إلى قريش فأخبرهم بذلك وطلب منهم الخروج والدفاع عن العير وأمر بالعير فأخذ بها نحو ساحل البحر ، وتركوا الطريق ومروا مسرعين ، ونزل جبرئيل عليه‌السلام على رسول الله صلى‌الله‌عليه‌وآله‌وسلم فأخبر أن العير قد أفلتت وأن قريشا قد أقبلت لتمنع عن عيرها وأمره بالقتال ، ووعده النصر ، فأخبر به رسول الله أصحابه فجزعوا من ذلك وخافوا خوفا شديدا إذ لم يتهيئوا للحرب ، فقال رسول الله : أشيروا عليّ. فقام أبو بكر فقال : يا رسول الله إنها قريش وخيلاؤها ما آمنت منذ كفرت ولا ذلت منذ عزّت ولم نخرج على هيئة الحرب. فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : اجلس فجلس. يُجادِلُونَكَ فِي الْحَقِّ بَعْدَ ما تَبَيَّنَ فقال صلى‌الله‌عليه‌وآله‌وسلم : أشيروا عليّ. فقام عمر فقال مثل مقالة أبي بكر ، فقال : اجلس ، ثم قام المقداد فقال : يا رسول الله إنها قريش وخيلاؤها ، وقد آمنا بك وصدقناك وشهدنا أن ما جئت به حق من عند الله ولو أمرتنا أن نخوض جو الفضاء وشوك الهراس لخضنا معك ولا نقول لك ما قالت بنو إسرائيل لموسى : « اذهب أنت وربك فقاتلا إنا هاهنا قاعدون » ولكنا نقول : « اذهب أنت وربك فقاتلا إنا هاهنا قاعدون » ولكنا نقول : « اذهب أنت وربك إنا معكما مقاتلون » . فجزاه النبي خيرا ثم جلس ثم قال : أشيروا عليّ. فقام سعد بن معاذ فقال : بأبي أنت وأمي يا رسول الله كأنك أردتنا ؟ قال : نعم قال : فلعلك خرجت على أمر قد أمرت بغيره. قال : نعم. قال : بأبي أنت وأمي يا رسول الله ، قد آمنا بك وصدقناك وشهدنا أن ما جئت به حق من عند الله ، فمر بنا بما شئت وخذ من أموالنا ما شئت. ثم قال : والله لو أمرتنا أن نخوض هذا البحر لخضناه معك. إلى أن قال : ولكن نعد لك الرواحل ونلقي عدونا فإنا صبّر عند اللقاء أنجاد في الحرب ، وإنا لنرجوا أن يقرّ الله عينيك بنا. فقال رسول الله : كأني بمصرع فلان هاهنا وبمصرع فلان هاهنا وبمصرع أبي جهل وعتبة وشيبة فإن الله وعدني إحدى الطائفتين ولن يخلف الله الميعاد (1) ، فنزلت الآية : ( كَما أَخْرَجَكَ ) فأمر بالرحيل حتى نزل ماء بدر وأقبلت قريش.` },
            { text: "كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَٰرِهُونَ", tafsir: `` },
            { text: "يُجَٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ", tafsir: `يا رسول الله بعض المؤمنين فيما دعوتهم إليه من محاربة قريش ( فِي الْحَقِ ) فإن الحرب واجب وحق ( بَعْدَ ما تَبَيَّنَ ) أنه حق ، ( 1) بحار الأنوار : ج 19 ص 247. كَأَنَّما يُساقُونَ إِلَى الْمَوْتِ وَهُمْ يَنْظُرُونَ (6) وَإِذْ يَعِدُكُمُ اللهُ إِحْدَى الطَّائِفَتَيْنِ أَنَّها لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذاتِ الشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ اللهُ أَنْ يُحِقَّ الْحَقَّ بِكَلِماتِهِ فإنهم كانوا يقولون : هلّا أخبرتنا لنعد عدتنا للحرب ، وهم يعلمون أنك لا تأمرهم إلّا بأمر الله سبحانه كما قال سبحانه : ( وَما يَنْطِقُ عَنِ الْهَوى * إِنْ هُوَ إِلَّا وَحْيٌ يُوحى ) (1) . ( كَأَنَّما ) هؤلاء المجادلين ( يُساقُونَ إِلَى الْمَوْتِ ) فيظنون أن سوقهم إلى الحرب موجب لهلاكهم حيث لم يعدوا لها العدة ( وَهُمْ يَنْظُرُونَ ) أي ينظرون إلى الموت عيانا ويرونه بأبصارهم ، فكيف يكون حال مثل هذا الإنسان ، كذلك حال هؤلاء المجادلين.` },
            { text: "وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَٰفِرِينَ", tafsir: `اذكروا أيها المسلمون ( إِذْ يَعِدُكُمُ اللهُ ) على لسان رسوله ( إِحْدَى الطَّائِفَتَيْنِ أَنَّها لَكُمْ ) إما طائفة العير فتغنمونها ، وإما قريش فتقتلونهم وتتخلصون من بعض أعدائكم ( وَتَوَدُّونَ ) أي تحبون وترغبون ( أَنَّ غَيْرَ ذاتِ الشَّوْكَةِ تَكُونُ لَكُمْ ) فإنهم كانوا يحبون أن يغنموا العير لئلّا يلاقوا مشقة الحرب ، والحال أن الحرب كانت لهم أكثر شوكة إذ تركز في العدو خوفهم وشوكتهم ، وكأن الشوكة مأخوذة من الشوك لأن في الحرب شوكا وليس الأمر سهلا ، فيكون تشبيها ، أو المراد بالشوكة : السلاح. ( وَيُرِيدُ اللهُ ) حيث أمركم بالحرب ( أَنْ يُحِقَّ الْحَقَّ بِكَلِماتِهِ ) أي ( 1) النجم : 4 و 5. وَيَقْطَعَ دابِرَ الْكافِرِينَ (7) لِيُحِقَّ الْحَقَّ وَيُبْطِلَ الْباطِلَ وَلَوْ كَرِهَ الْمُجْرِمُونَ (8) إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنَ الْمَلائِكَةِ مُرْدِفِينَ (9) يظهر الحق ، بما بيّنه وأوجبه عليكم من المقاتلة ( وَيَقْطَعَ دابِرَ الْكافِرِينَ ) أي يستأصلهم ، فإن « الدابر » هو الأصل ، أي يجذ الكفر من أصوله ، فإن وقعة بدر كانت أقوى الأسباب لنصرة المسلمين إلى الأبد وهزيمة الكافرين إلى الأبد. [9] وإنما أراد الله ذلك ( لِيُحِقَّ الْحَقَ ) أي يظهر حقيقة الإسلام ، وفي التكرار تركيز وتوطئة لقوله : ( وَيُبْطِلَ الْباطِلَ ) أي يظهر بطلانه بإهلاك الكفار ( وَلَوْ كَرِهَ ) ذلك ( الْمُجْرِمُونَ ) الذين أجرموا بالكفر والعصيان. [10] ولما بلغ أصحاب رسول الله كثرة قريش وما معها من السلاح والعتاد فزعوا واستغاثوا بالله وتضرعوا. « و » اذكروا أيها المسلمون ( إِذْ تَسْتَغِيثُونَ ) أي تطلبون الغوث والنصرة من ( رَبَّكُمْ فَاسْتَجابَ لَكُمْ ) دعاءكم وتضرعكم ( أَنِّي مُمِدُّكُمْ ) أي مرسل إليكم مددا ( بِأَلْفٍ مِنَ الْمَلائِكَةِ مُرْدِفِينَ ) أي بعضهم خلف بعض ، فهم مترادفون متتابعون في النزول إليكم. فإن قيل : كيف يمكن الجمع بين هذه الآية وبين قوله : ( بِثَلاثَةِ آلافٍ ) (1) ( بِخَمْسَةِ آلافٍ ) (2) ؟ ( 1) آل عمران : 125. ( 2) آل عمران : 126. وَما جَعَلَهُ اللهُ إِلاَّ بُشْرى وَلِتَطْمَئِنَّ بِهِ قُلُوبُكُمْ وَمَا النَّصْرُ إِلاَّ مِنْ عِنْدِ اللهِ إِنَّ اللهَ عَزِيزٌ حَكِيمٌ (10) فالجواب : إن الألف كانوا مقاتلين ، والبقية للبشارة وتقوية القلوب ، كما يقال : إن العاملين في المدينة عشرة ، فإذا قيل : إنهم أكثر ؟ أجيب بأن المائة مثلا إنما هي من حيث العدد والحركة والعمل للعشرة. و في الحديث : إن الرسول صلى‌الله‌عليه‌وآله‌وسلم لما نظر إلى كثرة عدد المشركين وقلة عدد المسلمين استقبل القبلة وقال : « اللهم أنجز لي ما وعدتني ، اللهم إن تهلك هذه العصابة لا تعبد في الأرض » (1) . فما زال يهتف بربه مادّا يديه حتى سقط رداؤه عن منكبه ، فأنزل الله الملائكة ، وقد قاتلت الملائكة وأسرت بعض المشركين. [11] ثم يذكر سبحانه أن إنزال الملائكة إنما كان لأجل تقوية قلوب المسلمين ، وإلّا فنصر الله سبحانه لا يحتاج إلى مدد ملك أو غيره ( وَما جَعَلَهُ اللهُ ) أي ما جعل الله الإمداد بالملائكة ( إِلَّا بُشْرى ) أي بشارة لكم بالنصر ، فإن الإنسان يستبشر بكثرة الأعوان وإن كان علم أنهم للسواد والكثرة فقط ( وَلِتَطْمَئِنَّ بِهِ ) أي بالإمداد ( قُلُوبُكُمْ ) فيزول الخوف والوسوسة عنها ( وَ ) إلّا في الحقيقة والواقع ( مَا النَّصْرُ ) أي ليس النصر ( إِلَّا مِنْ عِنْدِ اللهِ ) ولا تأثير للإمداد والإعداد وإنما هي روابط ووسائط إلّا من عند الله ( إِنَّ اللهَ عَزِيزٌ ) غالب بسلطانه ( حَكِيمٌ ) فيما يفعل ، وهذا لا يدل على عدم تهيئة الأسباب ، بل يدل على لزوم تهيئتها ، فإن الملائكة وقوى ما وراء الطبيعة بشائر ، ( 1) شرح نهج البلاغة لابن أبي الحديد : ج 3 ص 259. إِذْ يُغَشِّيكُمُ النُّعاسَ أَمَنَةً مِنْهُ وَيُنَزِّلُ عَلَيْكُمْ مِنَ السَّماءِ ماءً لِيُطَهِّرَكُمْ بِهِ وَيُذْهِبَ عَنْكُمْ رِجْزَ الشَّيْطانِ وَلِيَرْبِطَ عَلى قُلُوبِكُمْ وإلّا فالنصر من الله بأسبابه الظاهرية التي قررها هو سبحانه ، كما قال تعالى : ( وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ ) (1) . [12] ولما أمسى القوم المساء قبل الواقعة أخذ أصحاب الرسول النوم ، من كثرة التعب وقد كان إلقاء الله النوم عليهم ليذهب خوفهم ، ويتقووا على القتال غدا ، فإن من استراح ونام لم يقلق كما يقلق الساهر ، كما أن أعصابه تهدأ ، وقواه تكثر فيتمكن مما لا يتمكن عليه الساهر ، واحتلم كثير من المسلمين تلك الليلة ، وكان موضع نزولهم كثير الرمل ، مما سبب صعوبة الحركة ، فوسوس إليهم الشيطان قائلا : كيف أنتم على حق ، وقد أصابتكم الجنابة ، ومحلّكم غير صالح ، ولا ماء عندكم ، بينما المشركون على الماء ، فأنزل الله المطر ، حتى لبد الأرض ، واغتسلوا ، وارتووا. فاذكروا أيها المسلمون ( إِذْ يُغَشِّيكُمُ ) أي يستولي عليكم ( النُّعاسَ ) أي النوم ( أَمَنَةً ) أي أمانا ( مِنْهُ ) سبحانه ، فإنه لم يفعل ذلك إلّا لأجل أمنكم وراحتكم وإزالة الخوف عنكم ، و « الأمنة » الدعة التي تنافي المخافة ( وَيُنَزِّلُ عَلَيْكُمْ مِنَ السَّماءِ ماءً لِيُطَهِّرَكُمْ بِهِ ) من حدث الجنابة ( وَيُذْهِبَ عَنْكُمْ رِجْزَ الشَّيْطانِ ) أي وسوسته فإنه كان يوسوس في قلوبهم : كيف يكونون على حق ، وهم نجسون ، ومحلهم رمل ، وهم ظماء ( وَلِيَرْبِطَ عَلى قُلُوبِكُمْ ) أي ليشد ( 1) الأنفال : 61. وَيُثَبِّتَ بِهِ الْأَقْدامَ (11) إِذْ يُوحِي رَبُّكَ إِلَى الْمَلائِكَةِ أَنِّي مَعَكُمْ فَثَبِّتُوا الَّذِينَ آمَنُوا سَأُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ قلوبكم ويقويها ، فإن النوم ونزول المطر قوّيا قلوبهم حيث أزالا المخاوف والوساوس والأتعاب ( وَيُثَبِّتَ بِهِ ) أي بالمطر ( الْأَقْدامَ ) أي أقدامكم في الحرب بتلبد الرمل ، أو المراد تقوية القلب فإنه يكنى بذلك عنه ، أو المراد ذهاب الحالات الخمسة بالأمرين ؛ فالنوم للدعة ، والمطر لتطهير البدن عن نجاسة المني ، والاغتسال لذهاب رجس الشيطان ، وتقوية القلب عن وسوسته ، وتثبيت الأقدام بتلبد الرمل. [13] واذكروا أيها المسلمون ( إِذْ يُوحِي ) وهم وإن لم يروا ذلك ولم يسمعوه بآذانهم إلّا أنهم علموه ( رَبُّكَ ) يا رسول الله ( إِلَى الْمَلائِكَةِ ) المنزلين في وقعة بدر ( أَنِّي مَعَكُمْ ) وهذا لتقوية قلوب المسلمين ، وإلا فمن المعلوم أن الملائكة لا تفعل شيئا إلّا بأمر الله سبحانه ( فَثَبِّتُوا الَّذِينَ آمَنُوا ) بتقوية قلوبهم ودحر الشياطين عنهم ، فإن في القلب لمّتان : لمّة من الملائكة ولمة من الشيطان ، فالنوايا الحسنة وما أشبه من الملائكة ، والنوايا السيئة وما أشبه من الشياطين. ( سَأُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ ) أي الخوف من المؤمنين ، وقد كان ذلك ، فقد سلّط الله على الكفار رعبا عظيما ، حتى أن أبا لهب قال لأبي سفيان ـ بعد الواقعة ـ : كيف كان أمر الناس ؟ قال : لا شيء والله إلّا أن لقيناهم فمنحناهم أكتافنا يقتلوننا ويأسرونا كيف شاءوا ، وأيم الله مع ذلك مالت الناس ، رأينا رجالا بيضا على خيل بلق بين السماء والأرض ما تليق شيئا ولا يقوم لها شيء فَاضْرِبُوا فَوْقَ الْأَعْناقِ وَاضْرِبُوا مِنْهُمْ كُلَّ بَنانٍ (12) ذلِكَ بِأَنَّهُمْ شَاقُّوا اللهَ وَرَسُولَهُ وَمَنْ يُشاقِقِ اللهَ وَرَسُولَهُ فَإِنَّ اللهَ شَدِيدُ الْعِقابِ (13) ذلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكافِرِينَ عَذابَ النَّارِ (14) ( فَاضْرِبُوا ) أيها الملائكة ( فَوْقَ الْأَعْناقِ ) أي الرؤوس أو المذابح ، فإنهما فوق الأعناق ، أو هو كناية عن ضرب القفا للإذلال والإهانة ( وَاضْرِبُوا مِنْهُمْ ) أي من الكفار ( كُلَّ بَنانٍ ) أي أصابع اليد والرجل ، أو المعنى : جزّوا أعناقهم واقطعوا أطرافهم.` },
            { text: "لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ", tafsir: `` },
            { text: "إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُرْدِفِينَ", tafsir: `` },
            { text: "وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ", tafsir: `` },
            { text: "إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ", tafsir: `` },
            { text: "إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ", tafsir: `` },
            { text: "ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ", tafsir: `التعذيب والضرب فوق الأعناق والبنان بسبب أنهم ( شَاقُّوا اللهَ ) أي خالفوا الله ( وَرَسُولَهُ ) فكأنهم في شق والله والرسول في شق آخر ( وَمَنْ يُشاقِقِ اللهَ وَرَسُولَهُ ) ومن المعلوم أنه يكتفي بذكر الله وحده أو الرسول وحده ، ولكن ذلك لتعظيم الرسول حين يقرن باسم الله سبحانه ، وأنه الشخص المقابل لهم في المشاقة ( فَإِنَّ اللهَ شَدِيدُ الْعِقابِ ) في الدنيا بعقوبة الكافرين على أيدي المسلمين ، وفي الآخرة بإخلادهم في النار.` },
            { text: "ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَٰفِرِينَ عَذَابَ ٱلنَّارِ", tafsir: `« ذلك » إشارة إلى العذاب في الدنيا بالأسر والقتل ، و « كم » خطاب للكفار ( فَذُوقُوهُ ) أي ذوقوا هذا العذاب. و « الفاء » دخلت لإفادة الترتب على الكفر ( وَأَنَّ لِلْكافِرِينَ ) علاوة على هذا العقاب العاجل ( عَذابَ النَّارِ ) في الآخرة. ولا يخفى أن « الذوق » يستعمل كثيرا في غير الذوق باللسان ، باعتبار إدراك الإنسان له كما يدرك باللسان المذوقات ، وهو يستعمل بالنسبة إلى الألم الروحي ، كما يا أَيُّهَا الَّذِينَ آمَنُوا إِذا لَقِيتُمُ الَّذِينَ كَفَرُوا زَحْفاً فَلا تُوَلُّوهُمُ الْأَدْبارَ (15) وَمَنْ يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُ إِلاَّ مُتَحَرِّفاً لِقِتالٍ أَوْ مُتَحَيِّزاً إِلى فِئَةٍ يقال : « ذق الذل » ، وبالنسبة إلى الألم الجسمي ، كما يقال : « ذق السوط » ، قال سبحانه : ( فَأَذاقَهَا اللهُ لِباسَ الْجُوعِ وَالْخَوْفِ ) (1) ، وقال : ( ذُقْ إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ ) (2) .` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ", tafsir: `الخطاب عام لكل مؤمن ، وإن كان نزول الآية بمناسبة قصة بدر ( إِذا لَقِيتُمُ الَّذِينَ كَفَرُوا ) من اللقاء في الحرب ( زَحْفاً ) « حال » أي حال كونهم وإياكم زاحفين متدانين للقتال ، فإن الزحف بمعنى الدنو ( فَلا تُوَلُّوهُمُ الْأَدْبارَ ) أي لا تنهزموا بأن تجعلوا ظهوركم إليهم ، فإن الإنسان لا يجعل ظهره إلى ساحة القتال إلّا إذا أراد الفرار.` },
            { text: "وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ", tafsir: `أي من يجعل ظهره إليهم يوم القتال ، وإنما قال « يومئذ » لأنه فهم من قوله : ( إِذا لَقِيتُمُ إِلَّا ) إذا كان ( مُتَحَرِّفاً لِقِتالٍ ) أي تاركا موقفه إلى موقف آخر أصلح للقتال من موقفه الأول ، و « التحرّف » الزوال عن جهة الاستواء إلى جهة الحرف بمعنى الطرف ، واللفظ ، حال ، أي : في حال كونه قاصدا الطرف حتى يكون أمكن في الحرب ( أَوْ مُتَحَيِّزاً إِلى فِئَةٍ ) طلب حيزا غير حيزه السابق ، أي مكان جديد ، يقال : « فلان متحيز إلى فلان » أي ( 1) النحل : 113. ( 2) الدخان : 50. فَقَدْ باءَ بِغَضَبٍ مِنَ اللهِ وَمَأْواهُ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ (16) فَلَمْ تَقْتُلُوهُمْ وَلكِنَّ اللهَ قَتَلَهُمْ وَما رَمَيْتَ إِذْ رَمَيْتَ وَلكِنَّ اللهَ رَمى منحاز نحوه ، منضم إليه. فالمعنى : أنه ولّى دبره لينضم إلى جماعة يستعين بهم في القتال ، فإن الإنسان وحده يجترئ عليه العدو أكثر مما إذا كان مع جماعة ( فَقَدْ باءَ ) خبر « ومن يولهم » أي أن المولي دبره يرجع ( بِغَضَبٍ مِنَ اللهِ ) فكأنه كان ذاهبا إلى الحرب برضى الله ، والآن بفراره رجع يحمل الغضب ( وَمَأْواهُ ) أي مصيره ( جَهَنَّمُ وَبِئْسَ الْمَصِيرُ ) وبهذا يستدل على أن الفرار من الزحف كبيرة موبقة. [18] ثم ذكر سبحانه أن السبب الحقيقي في انهزام الكفار إنما كان هو الله سبحانه ( فَلَمْ تَقْتُلُوهُمْ ) أي لم تقتلوا الكفار أنتم أيها المسلمون. و « النفي عنهم » باعتبار كونهم السبب الأضعف ، فلو لا تشجيع الله سبحانه بإنزال الملائكة وإنزال المطر وتقوية قلوبهم ومساعدة الملائكة لهم في القتل والأسر لم يتمكنوا من الغلبة عليهم ، ومن المتعارف أن ينسب الفعل إلى أقوى السببين ( وَلكِنَّ اللهَ قَتَلَهُمْ ) بتهيئة الأسباب وإلقاء الرعب في قلوب الكفار حيث انهارت أعصابهم ( وَما رَمَيْتَ ) يا رسول الله ، أو أيها المسلم ( إِذْ رَمَيْتَ ) والمراد بالأول : الرمي المصيب ، فإن الفعل ينفى عمن لم تكن نتيجة الفعل بقدرته ، كما يقال لمن ألقى حجرا بدون معرفة فاصطاد طائرا : « فما صدت أنت وإنما صادته الصدفة » . ولعل المراد ب « الرمي » ، رمي القوم بالهلاك ، كما يقال : « رماه الله بهلاك ونكال » . ( وَلكِنَّ اللهَ رَمى ) فإنه كان السبب الأقوى في هلاكهم ونكالهم. وَلِيُبْلِيَ الْمُؤْمِنِينَ مِنْهُ بَلاءً حَسَناً وذكر جمع من المفسرين : أن المراد بذلك ، رمي الكفار بالتراب ، فإن جبرئيل عليه‌السلام قال للنبي صلى‌الله‌عليه‌وآله‌وسلم يوم بدر : خذ قبضة من تراب فارمهم بها. فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم لما التقى الجمعان لعلي عليه‌السلام : أعطني قبضة من حصى الوادي. فناوله كفا من حصى عليه تراب فرمى به في وجوه القوم وقال : شاهت الوجوه ، فلم يبق مشرك إلّا دخل في عينه وفمه ومنخريه منه شيء وتبعهم المؤمنون يقتلونهم ويأسرونهم وكانت تلك الرمية سبب هزيمة القوم ، ولما أن اصطف القوم برز عتبة وشيبة والوليد للقتال وطلبوا المبارز فخرج إليهم بعض المسلمين فلم يرضوا بهم لما جرت العادة من عدم احتشام القرن إلّا بقرنه حتى برز إليهم عليّ عليه‌السلام وحمزة وعبيدة ، ودارت المعركة بنصرة هؤلاء ، وقتل أولئك ، وهنا حمي الوطيس واستعرت الحرب ولم تنكشف إلّا بهزيمة الكفار وقتل جماعة كبيرة منهم ، وأخذ المسلمون يأسرونهم والملائكة تعينهم في الأسر كما أعانتهم في القتل. فكان المسلم يشير بسيفه أو رمحه ولما يصل إلى الكافر فإذا به يخر قتيلا تقتله الملائكة ، وكذلك الأسر. حتى أن العباس أسره أبو اليسر وكان العباس جسيما وأبو اليسر نحيفا ، فقال له الرسول صلى‌الله‌عليه‌وآله‌وسلم : كيف أسرت العباس يا أبا اليسر ؟ فقال : يا رسول الله لقد أعانني عليه رجل ما رأيته قبل ذلك ولا بعده. فقال الرسول صلى‌الله‌عليه‌وآله‌وسلم : لقد أعانك عليه ملك كريم (1) . وكل هذه كانت للبشرى وإنما النصر كان من عند الله. ( وَ ) قد فعل الله سبحانه ما فعل ( لِيُبْلِيَ ) أي لينعم على ( الْمُؤْمِنِينَ مِنْهُ ) أي من عنده سبحانه ( بَلاءً حَسَناً ) أي نعمة جسيمة ، ( 1) بحار الأنوار : ج 19 ص 227. إِنَّ اللّهَ سَمِيعٌ عَلِيمٌ (17) ذَلِكُمْ وَأَنَّ اللّهَ مُوهِنُ كَيْدِ الْكَافِرِينَ (18) إِن تَسْتَفْتِحُواْ فَقَدْ جَاءكُمُ الْفَتْحُ ف ـ « الواو » على هذا استئنافية متعلقة بفعل مقدّر ، كما قدّرناه ، أو المراد : ليمتحن المؤمنين امتحانا حسنا ، فإن البلاء يأتي بمعنى النعمة كما يأتي بمعنى الاختبار ، وإنما يقال للنعمة : بلاء ، لأن أصل البلاء ما يظهر به الأمر من الشكر والصبر ، فالنعمة بلاء لأنها تظهر الشكر ، والمصيبة بلاء لأنها تظهر الصبر ( إِنَّ اللهَ سَمِيعٌ ) لأقوالكم ( عَلِيمٌ ) بضمائركم ونياتكم. وفي الحرب تظهر أقوال ، وتجول في الصدر نيات ، فمن الأحرى أن يحفظ الإنسان قلبه ولسانه لئلّا ينحرفان عن نهج الصواب بمحضر من يسمع ويعلم كل شيء. [19] الأمر ( ذلِكُمْ ) أي أن الأمر كما ذكرنا من القصة ، وهذا كما أن من يذكر قصة يقول بعدها : « هكذا » وهذا شبه تأكيد للكلام السابق ، ف « ذلك » إشارة و « كم » للخطاب ، أي : أخاطبكم أيها المؤمنون أن الأمر كذلك ( وَأَنَّ اللهَ مُوهِنُ كَيْدِ الْكافِرِينَ ) هذا عطف على « ذلكم » أي أن الغرض كان بلاء المؤمنين ووهن كيد الكافرين. هذا بناء على رجوع « ذلكم » إلى البلاء المستفاد من قوله : « ليبلي المؤمنين » ، وإلّا كان « وأن الله » استئنافية. [20] وحيث بيّن سبحانه أن الله يوهن كيد الكافرين خاطب الكفار بقوله : ( إِنْ تَسْتَفْتِحُوا ) أيها الكفار ( فَقَدْ جاءَكُمُ الْفَتْحُ ) وهذا تهكّم ، فإن أبا سفيان دعا قبل الواقعة بقوله : « اللهم أهلك أضل الفريقين وأقطعهما للرحم » ، فقد استجاب الله دعاءه وأهلك أضل الفريقين وأقطعهما للرحم. والمراد ب « الاستفتاح » طلب الفتح ، كأن وَإِنْ تَنْتَهُوا فَهُوَ خَيْرٌ لَكُمْ وَإِنْ تَعُودُوا نَعُدْ وَلَنْ تُغْنِيَ عَنْكُمْ فِئَتُكُمْ شَيْئاً وَلَوْ كَثُرَتْ وَأَنَّ اللهَ مَعَ الْمُؤْمِنِينَ (19) يا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللهَ وَرَسُولَهُ وَلا تَوَلَّوْا عَنْهُ وَأَنْتُمْ تَسْمَعُونَ (20) وَلا تَكُونُوا كَالَّذِينَ قالُوا سَمِعْنا وَهُمْ الذي يقع في مشكلة قد انسدت عليه الأبواب فيطلب فتحها ليتخلص من المشكلة. ثم يرغّبهم سبحانه في الانتهاء عن كفرهم ( وَإِنْ تَنْتَهُوا ) عن الكفر ومعاداة المسلمين ( فَهُوَ خَيْرٌ لَكُمْ ) في دنياكم وآخرتكم ( وَإِنْ ) لم تنتهوا و ( تَعُودُوا ) إلى كفركم ومشاقتكم لله والرسول ( نَعُدْ ) إلى ما رأيتم من إهلاككم وإذلالكم ، وبأسنا لا يقف أمامه تجمع وكثرة ( وَلَنْ تُغْنِيَ عَنْكُمْ فِئَتُكُمْ شَيْئاً ) أي لا تفيد بكم جماعتكم شيئا ( وَلَوْ كَثُرَتْ ) فإن النجاح ليس بالكثرة وإنما بالقوة التي هي متوفرة لدى المؤمنين ( وَأَنَّ اللهَ مَعَ الْمُؤْمِنِينَ ) ومن المعلوم انطباق هذه الآيات في كل زمان ومكان بشرط أن يعمل المسلمون على شرائط الإيمان. [21] ثم خاطب سبحانه المؤمنين أن يلتزموا بما هو سبب نجاحهم بقوله : ( يا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللهَ وَرَسُولَهُ ) واختصاص الخطاب بالمؤمنين ، مع أن الإطاعة واجبة على الجميع ، لأنهم هم المصغون المنتفعون بالخطاب دون غيرهم ( وَلا تَوَلَّوْا عَنْهُ ) أي لا تعرضوا عن الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَ ) الحال ( أَنْتُمْ تَسْمَعُونَ ) دعاءه لكم وأمره ونهيه إياكم ، فإن المعرض بعد العلم أشد عقوبة عن المعرض بلا علم.` },
            { text: "فَلَمْ تَقْتُلُوهُمْ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمْ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ", tafsir: `` },
            { text: "ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ", tafsir: `` },
            { text: "وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ", tafsir: `وهم اليهود والمنافقون ( وَهُمْ لا يَسْمَعُونَ (21) إِنَّ شَرَّ الدَّوَابِّ عِنْدَ اللهِ الصُّمُّ الْبُكْمُ الَّذِينَ لا يَعْقِلُونَ (22) وَلَوْ عَلِمَ اللهُ فِيهِمْ خَيْراً لَأَسْمَعَهُمْ لا يَسْمَعُونَ ) حقيقة ، إذ لو سمعوا ووعوا لعلموا ، فعدم علمهم دليل على عدم سماعهم سماع متعظ واع ، فإنه يقال للعالم التارك لعلمه : « إنه غير عالم » ، كما يقال لمن سمع قول الرشد ، فسلك سبيل الغي : « أنه لم يسمع » . [23] وإذ أمر الله سبحانه المؤمنين بالسماع النافع المقترن بالعمل حذّرهم أن يكونوا كالدابة التي لا تسمع إلّا نداء من غير أن تعقل وتعمل حسب ما سمعت ، ولا تنطق بالخير والأمر بالمعروف والنهي عن المنكر ( إِنَّ شَرَّ الدَّوَابِّ عِنْدَ اللهِ ) الكفار ، إنهم أشر من الدابة ، حيث إن الدابة لا تعقل ، وهؤلاء يعقلون ثم يعرضون ( الصُّمُّ الْبُكْمُ ) « صمّ » جمع « أصم » : وهو الذي لا يسمع ، و « بكم » جمع « أبكم » : وهو الذي لا يتكلم ( الَّذِينَ لا يَعْقِلُونَ ) عقلا مثمرا ، وإلا فهم عقلاء ، فإن هؤلاء شر ما دبّ على وجه الأرض من الحيوان حيث لم ينتفعوا بما سمعوا من الحق ، ولم يتكلموا به. روي عن الإمام الباقر عليه‌السلام : « إنها نزلت في بني عبد الدار ، لم يكن أسلم منهم غير مصعب بن عمير وحليف لهم يقال له : سويبط » (1) .` },
            { text: "إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ", tafsir: `` },
            { text: "وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ", tafsir: `قبولا للحق وإذعانا به وإنصافا في الأمر ( لَأَسْمَعَهُمْ ) إسماعا نافعا ، ولكنه علم أن ليس فيهم خير ، ولا رجاء ( 1) بحار الأنوار : ج 9 ص 96. وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوْا وَهُمْ مُعْرِضُونَ (23) بهم ، فلذا تركهم مغلقي القلوب ، وهذا كما تقول : « لو علمت في هذه الأرض قابلية للزرع لحرثتها » ، حيث إنها لا تصبح قابلة للزراعة حتى بالحرث. وهكذا قلب الإنسان القابل وقلب الإنسان غير القابل ، فإن أغشية الكفر قد شملتهما ، لكن الله سبحانه يزيل الغشاء عن قلب القابل حيث يعرف فيه الخير ، ولا يزيله عن قلب غير القابل حيث يعرف فيه عدم الخير. وبهذا تحقق أنه لا مجال للإشكال بأنه إن أريد من « الإسماع » المعنى الظاهري ، فقد أسمع الله سبحانه كل برّ وفاجر ؛ فلا يناسبه التعليق على « لو » الامتناعية ، وإن أريد منه تطهير القلوب تكوينا فإن الله لو فعل ذلك لكان فيه من الخير ؛ فلا يناسبه ما يفهم من الآية من عدم إمكان الخير. وحاصل الجواب : أن هناك ثلاث مراتب : الإسماع الظاهري ، وإزالة الأغشية ، وطهارة القلوب ذاتا. فإزالة الأغشية خاصة بالمؤمن ، بينما الإسماع عام لكل واحد ، فالمعنى : لو علم الله الطهارة الذاتية في قلوبهم لأزال الأغشية المظلمة عنها ، علاوة على الإسماع ، ولكن علم أن ذلك لا ينجح ، فإن قلوبهم كالأرض السبخة التي لا ينفع معها الحرث ، فلذا تركهم وشأنهم. ( وَلَوْ أَسْمَعَهُمْ ) بهذا النحو من الإسماع بإزالة الأغشية ( لَتَوَلَّوْا ) أي أعرضوا ، لأن قلوبهم سبخة لا ينفعها حتى إزالة الأغشية ( وَهُمْ مُعْرِضُونَ ) عن الحق. وربما أورد بأنه : كيف يمكن ذلك ، والحال أن لازم هذا النحو يا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذا دَعاكُمْ لِما يُحْيِيكُمْ من القياس المنطقي ـ بحذف الأوسط ـ « لو علم الله فيهم خيرا لتولوا » ، مع وضوح أنه لو علم الله فيهم خيرا لم يتولوا ؟ والجواب : إن الكلام جار مجرى العرف ، فليس هذا قياسا واحدا بل قياس وزيادة تقديره « لو علم الله فيهم خيرا لأسمعهم ، لكنه علم فيهم عدم الخير فلم يسمعهم » ، « ولو أسمعهم مع علمه عدم الخير فيهم لتولوا » وهذا كما تقول عن ولد لك غير قابل للكسب : « لو علمت أنه غير كاسب لزودته برأس مال » ، « ولو زودته لأتلف » تريد : لو زودته والحال أني أعلم عدم قابليته. [25] وبعد ما ذكر سبحانه وجوب إطاعة الله والرسول ، ألمع إلى أن في الاستجابة كل الخير كما أراهم ذلك فقال : ( يا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا ) أي أجيبوا. ولعل السر في الإتيان بباب « الاستفعال » المفيد للطلب ، إفادة أن اللازم كون الجواب عن القلب والضمير ، لا بمجرد اللفظ والظاهر ، فإن طلب الإنسان لأن يجيب إنما بنبع من قلبه وباطنه ( لِلَّهِ وَلِلرَّسُولِ ) وقد تقدم أن ذكر الرسول تعظيما له ، ولأنه الداعي الذي يراه الإنسان ويقابله ( إِذا دَعاكُمْ لِما يُحْيِيكُمْ ) فإن الحياة الكاملة إنما هي بالإيمان ، إذ الحياة بمعنى الحس والحركة مرتبة ضعيفة من الحياة ، والمرتبة الأعلى بمعنى السعادة الملازمة للعلم والفضيلة والرفاه والأمن والصحة ، هذا بالنسبة إلى الدنيا وكذلك بالنسبة إلى الآخرة ، فإن حياة الجنة هي الحياة الكاملة التي تستحق أن تسمى حياة ، أما حياة النار فإنها لا تستحق اسم الحياة ، ولذا قال سبحانه : ( لا وَاعْلَمُوا أَنَّ اللهَ يَحُولُ بَيْنَ الْمَرْءِ وَقَلْبِهِ وَأَنَّهُ إِلَيْهِ تُحْشَرُونَ (24) يَمُوتُ فِيها وَلا يَحْيى ) (1) . و « إذا » ليست شرطا له مفهوم ، بل المراد إفادة أن دعوة الرسول صلى‌الله‌عليه‌وآله‌وسلم إنما تكون لما فيه حياة الناس. وتوحيد الفعل مع أن الله والرسول اثنان ، باعتبار أن دعوتهما واحدة ، أو كان باعتبار كل واحد منهما ، كما قال : ( طَعامِكَ وَشَرابِكَ لَمْ يَتَسَنَّهْ ) (2) . إنه سبحانه يريد أن تستجيبوا عن إرادة وطواعية وإن كان يقدر على كل شيء ( وَاعْلَمُوا أَنَّ اللهَ يَحُولُ بَيْنَ الْمَرْءِ وَقَلْبِهِ ) فمن هذه قدرته ، أليس يقدر على جبركم أن تؤمنوا ؟ ومعنى « الحيلولة بين المرء وقلبه » أن لا تطيع الأعضاء القلب فيما يأمر وينهى ، بأن يريد قلبه شيئا فلا تطيعه الأعضاء بمنع الله سبحانه عن الإطاعة ، وكذا العكس بأن تنقل الأعضاء ـ كالعين والأذن والذوق والأنف واللامسة ـ إلى القلب معلومات فلا يفهمها ، فإن القلب كالسلطان يعطي ويأخذ ، والله قادر على أن يفصل بينه وبين رعيته وجيوشه ( وَأَنَّهُ إِلَيْهِ تُحْشَرُونَ ) أي واعلموا أنكم تجمعون إليه للجزاء والحساب. ومعنى « إليه » أي إلى الموضع المقرر للجزاء ، كما يقال : « ذهب إلى الله » لمن يذهب إلى الحج ، فيراد المكان المقرر لإتيان الأعمال. إن قلوبكم بين يديه وحشركم إليه ، فأذعنوا له حتى تحيون حياة طيبة. ( 1) طه : 75. ( 2) البقرة : 260. وَاتَّقُوا فِتْنَةً لا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنْكُمْ خَاصَّةً وَاعْلَمُوا أَنَّ اللهَ شَدِيدُ الْعِقابِ (25) وَاذْكُرُوا إِذْ أَنْتُمْ قَلِيلٌ` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ", tafsir: `` },
            { text: "وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ", tafsir: `أي خافوا ، إن لم تستجيبوا ( فِتْنَةً ) وبلاء عامّا ( لا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنْكُمْ خَاصَّةً ) فإن أفراد الأمة إذا سكتوا على المنكر عمّهم الله بالعقاب ، أولئك بالعصيان وهؤلاء بالسكوت ، كمن لا يأخذ بيدي من يريد ثقب السفينة فإنه يقرن مع الثاقب. كما مثل الرسول صلى‌الله‌عليه‌وآله‌وسلم . ومن قرأ : « لتصيبن » أدخل الساكت في جملة الظالمين ، لأنه ظالم بسكوته. ويكون المعنى على هذا : إن الفتنة تصيبكم أيها الظلمة فقط ، فلا تقولوا : كيف تصيبنا الفتنة فقط ونحن في جملة غير الظالمين ؟ تريدون بذلك عدم إصابتكم بالفتنة لأنكم بين أظهر غير الظالمين ، فإن الله سبحانه قادر على إصابتكم فقط ، كما أصابت الفتنة أصحاب السبت دون الذين نهوهم ووعظوهم. هذا ، ولكنا حيث نرجح عدم الزيادة والنقيصة في القرآن الحكيم ، وأن ما بين دفتيه هو القرآن المنزل حتى أن النظم أيضا منه صلى‌الله‌عليه‌وآله‌وسلم ، نوجّه الروايات الواردة « الخاصة بالقراءات » بأنها تأويل واجتهاد لا نزول ووحي. ( وَاعْلَمُوا أَنَّ اللهَ شَدِيدُ الْعِقابِ ) فإذا أخذتم يكون أخذه أليما شديدا ، فاستجيبوا لله والرسول ، فإن فيه حياتكم ، وفي غيره النكال والعقاب. [27] وقد رأيتم كيف تفضّل الله عليكم حين استجبتم له وللرسول ( وَاذْكُرُوا ) أيها المؤمنون ( إِذْ أَنْتُمْ قَلِيلٌ ) في العدد مُسْتَضْعَفُونَ فِي الْأَرْضِ تَخافُونَ أَنْ يَتَخَطَّفَكُمُ النَّاسُ فَآواكُمْ وَأَيَّدَكُمْ بِنَصْرِهِ وَرَزَقَكُمْ مِنَ الطَّيِّباتِ لَعَلَّكُمْ تَشْكُرُونَ (26) يا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللهَ وَالرَّسُولَ ( مُسْتَضْعَفُونَ فِي الْأَرْضِ ) يطلب الأعداء ضعفكم فينزلون بكم أنواع الإهانة والأذى ( تَخافُونَ أَنْ يَتَخَطَّفَكُمُ النَّاسُ ) أي يأخذونكم فجأة ، و « الاختطاف » إما لأجل السجن أو لأجل القتل أو لأجل الأذية ، والمراد ب « الناس » الكفار ( فَآواكُمْ ) أي جعل الله سبحانه لكم مأوى تأوون إليه ، وهي المدينة ( وَأَيَّدَكُمْ ) قوّاكم ( بِنَصْرِهِ ) لكم على أعدائكم حتى صرتم أقوياء بفضله سبحانه ( وَرَزَقَكُمْ مِنَ الطَّيِّباتِ ) فإنهم في مكة كانوا فقراء لا يجدون طعاما ولا شرابا ، حتى إذا صاروا في المدينة زرعوا واتجروا فرزقوا من الطيبات ( لَعَلَّكُمْ تَشْكُرُونَ ) أي لكي تشكروا فضله سبحانه ، ونعمته وإحسانه عليكم. [28] ولما ذكر سبحانه وجوب استجابة المؤمن لله ورسوله ، نهى عن الخيانة له وللرسول بقوله سبحانه : ( يا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللهَ ) بترك أوامره ( وَالرَّسُولَ ) بترك شريعته. وقد نزلت هذه الآية في أبي لبابة ، وإن كانت هي عامة لكل من يريد الخيانة. فقد ورد أن الرسول صلى‌الله‌عليه‌وآله‌وسلم حاصر يهود بني قريضة إحدى وعشرين ليلة ـ لما خانوا عهده ـ فسألوه الصلح على ما صالح عليه بنوا النظير بأن يصيروا إلى أذرعات وأريحا من أرض الشام فأبى إلّا أن ينزلوا على حكم سعد بن معاذ فقالوا : أرسل إلينا أبا لبابة وكان مناصحا لهم لأن عياله وماله وولده كانوا عندهم ، فبعثه رسول الله فقالوا : ما ترى يا أبا وَتَخُونُوا أَماناتِكُمْ وَأَنْتُمْ تَعْلَمُونَ (27) وَاعْلَمُوا أَنَّما أَمْوالُكُمْ وَأَوْلادُكُمْ فِتْنَةٌ لبابة أ ننزل على حكم سعد ؟ فأشار بيده إلى حلقه « إنه الذبح » فلا تفعلوا ، فأتى جبرئيل رسول الله صلى‌الله‌عليه‌وآله‌وسلم فأخبره بذلك ، قال أبو لبابة : فو الله ما زالت قدماي من مكانهما حتى عرفت أني خنت الله ورسوله. فلم يرجع إلى الرسول بل جاء إلى المسجد وشد نفسه بسارية من سواري المسجد وقال : لا والله لا أذوق طعاما ولا شرابا حتى أموت أو يتوب الله علي. فمكث أياما لا يذوق طعاما ولا شرابا حتى خرّ مغشيّا عليه ثم تاب الله عليه ، ونزلت : ( وَآخَرُونَ اعْتَرَفُوا بِذُنُوبِهِمْ خَلَطُوا عَمَلاً صالِحاً وَآخَرَ سَيِّئاً عَسَى اللهُ أَنْ يَتُوبَ عَلَيْهِمْ إِنَّ اللهَ غَفُورٌ رَحِيمٌ ) (1) ، فقيل له : يا أبا لبابة قد تاب الله عليك. قال : لا والله لا أحل نفسي حتى يكون رسول الله هو الذي يحلني. فجاءه فحله بيده ثم قال أبو لبابة : إن من تمام توبتي أن أهجر دار قومي التي أصبت فيها الذنب وأن انخلع من مالي. فقال النبي صلى‌الله‌عليه‌وآله‌وسلم : يجزيك الثلث أن تصدّق به (2) . ( وَ ) لا ( تَخُونُوا أَماناتِكُمْ ) أي أمانة بعضكم عند بعض من مال ، أو عرض ، أو ما أشبه ( وَأَنْتُمْ تَعْلَمُونَ ) أن الخيانة محرّمة موجبة للعقاب والعذاب. ومن الممكن أن تكون جملة « وتخونوا » استفهامية إنكارية ، أي : « كيف تخونوا أماناتكم في حال العلم » ، وسميت خيانة الله والرسول خيانة الأمانة لنفس الإنسان.` },
            { text: "وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ", tafsir: `` },
            { text: "وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ", tafsir: `أي تيقنوا ( أَنَّما أَمْوالُكُمْ وَأَوْلادُكُمْ فِتْنَةٌ ) امتحان وابتلاء ( 1) التوبة : 102. ( 2) راجع تفسير القمي : ج 1 ص 303. وَأَنَّ اللهَ عِنْدَهُ أَجْرٌ عَظِيمٌ (28) يا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَتَّقُوا اللهَ يَجْعَلْ لَكُمْ فُرْقاناً وَيُكَفِّرْ عَنْكُمْ سَيِّئاتِكُمْ وَيَغْفِرْ لَكُمْ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ (29) وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا ليختبر الله سبحانه من يرجّح أمر الله على ماله وولده ، ومن يرجّحهما على أمره سبحانه ، فإن أبا لبابة حمله على ما فعل أن أمواله وأولاده كانت عند اليهود فخاف إن نصح لله والرسول أن تذهب أمواله وأولاده. ( وَأَنَّ اللهَ عِنْدَهُ أَجْرٌ عَظِيمٌ ) فمن رجّح أمره سبحانه على ماله وولده أوجر بأعظم أجر. [30] إن الأمانة حمل ثقيل لا يقوم بها إلّا من اتقى الله ، ولذا يقول سبحانه : ( يا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَتَّقُوا اللهَ يَجْعَلْ لَكُمْ فُرْقاناً ) فإن من اتقى الله سبحانه صار ميزان الخير والشر ملكة له ، فيفرق بين الحق والباطل بتلك الملكة الحاصلة بالتقوى ، فإن عرفان الإنسان أن عليه مراقبا يحدّد موقفه من الأعمال والأقوال. ( وَيُكَفِّرْ عَنْكُمْ سَيِّئاتِكُمْ ) التي عملتموها. ومعنى « تكفير السيئات » سترها ، فإن التكفير بمعنى الستر والتغطية ( وَيَغْفِرْ لَكُمْ ) ذنوبكم بإزالتها ، فإن الستر غير الإزالة ، وهما نعمتان وفضلان ( وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ ) فإنه يتفضل عليكم بالتكفير والمغفرة وجعل الفرقان. [31] وإذ تقدم الكلام حول نصرة المؤمنين في بدر بعد أن كانوا قليلا مستضعفين في مكة ، بيّن سبحانه حالة النبي صلى‌الله‌عليه‌وآله‌وسلم قبل الهجرة ( وَ ) اذكر يا رسول الله ( إِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا ) أي يدبرون مؤامرة لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ اللهُ وَاللهُ خَيْرُ الْماكِرِينَ (30) ( لِيُثْبِتُوكَ ) أي يقيّدوك ويسبحونك فتثبت في مكة لا تقدر على الإرشاد والتبليغ ( أَوْ يَقْتُلُوكَ ) ويستأصلوا شأفتك ( أَوْ يُخْرِجُوكَ ) ويبعدوك ، بإرسالك إلى بعض المحالّ النائية ، حتى لا تتصل بأصحابك وبالناس ( وَيَمْكُرُونَ ) تأكيد ، تهيئة لقوله : ( وَيَمْكُرُ اللهُ ) أي يدبر الله سبحانه الأمر خفية ، فإن التدبير لا يكون إلّا خفية ( وَاللهُ خَيْرُ الْماكِرِينَ ) فإنه أعرف بطرق العلاج. والفرق بين مكر الله سبحانه ومكر الناس أن الأول لا يكون إلّا بحق ، والثاني لا يستعمل ـ غالبا ـ إلّا إذا كان بباطل. إن هذه الآية الكريمة نزلت في قصة هجرة النبي صلى‌الله‌عليه‌وآله‌وسلم وذلك أن قريشا اجتمعت فخرج من كل بطن أناس إلى دار الندوة ليتشاوروا فيما يصنعون برسول الله صلى‌الله‌عليه‌وآله‌وسلم فإذا شيخ قائم بالباب وإذ ذهبوا إليه ليخرجوه قال : أنا شيخ من مصر « أو نجد » أدخلوني معكم. قالوا : ومن أنت يا شيخ ؟ فقال : أنا شيخ من مصر « أو نجد » ولي رأي أشير به عليكم. فدخلوا وجلسوا فتشاوروا وهو جالس وأجمعوا أمرهم على أن يوثقوا الرسول صلى‌الله‌عليه‌وآله‌وسلم ، قال الشيخ : هذا ليس بالرأي ، فإن فعلتم هذا ذهب أصحابه وفكّوا وثاقه ، ومحمد رجل حلو اللسان فإنه يفسد عليكم أبناءكم وخدمكم وما ينفع أحدكم بهم بعد أن أفسدهم محمد. ثم تشاوروا فأجمعوا أمرهم على أن يخرجوه من بلادهم ، فقال الشيخ : هذا ليس بالرأي ؛ إنه إن خرج أحاط به الناس الأعراب لحلو منطقه وأفسد عليكم من الخارج. فاستصوبوا رأيه ثم سألوه الرأي قال : أخرجوا من كل بطن من العرب إنسانا يجتمعون عليه ويضربونه ضربة رجل واحد حتى يقتلوه ، فيفرّق دمه في القبائل ولا تتمكن عشيرته من المطالبة بدمه ويجبرون على أخذ الدية ، فتستريحون منه. فأخذوا برأي الشيخ ، وكان هو الشيطان « لعنه الله » تزيّ بزيّ البشر. ونزل جبرئيل على الرسول يخبره بمكر أهل الندوة ، ويأمره بالفرار ليلا ، وأن ينيم عليا عليه‌السلام مكانه ليشتبه عليهم الأمر ، فلما أمسى المساء جاء الفتيان مسلّحين ، وأرادوا أن يدخلوا على الرسول صلى‌الله‌عليه‌وآله‌وسلم لكن أبا لهب حال دون ذلك ، وقال : لا أدعكم أن تدخلوا عليه بالليل فإن في الدار صبيانا ونساء ولا نأمن أن تقع بهم يد خاطئة ، فنحرسه الليلة فإذا أصبحنا دخلنا عليه. فناموا حول حجرة رسول الله صلى‌الله‌عليه‌وآله‌وسلم وأمر رسول الله أن يفرش له وقال لعلي عليه‌السلام : أفدني بنفسك. قال : نعم يا رسول الله. قال : نم على فراشي والتحف ببردتي. وكان الفتيان ينظرون من شقوق الباب فيرون في مكان الرسول صلى‌الله‌عليه‌وآله‌وسلم شخصا نائما فظنوه الرسول صلى‌الله‌عليه‌وآله‌وسلم . وجاء جبرئيل فأخذ بيد رسول الله صلى‌الله‌عليه‌وآله‌وسلم فأخرجه من بين ظهراني الكفار وهم نيام وهو يقرأ عليهم : ( وَجَعَلْنا مِنْ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْناهُمْ فَهُمْ لا يُبْصِرُونَ ) (1) . و قال له جبرئيل : خذ على طريق « ثور » وهو جبل على طريق « منى » له سنام كسنام الثور فدخل غارا كان فيه ، فلما أصبحت قريش وبثوا إلى الحجرة وقصدوا الفراش فقام علي عليه‌السلام في وجوههم وقال : ما شأنكم ؟ قالوا له : أين محمد ؟ قال : أ جعلتموني عليه رقيبا ، ألستم ( 1) يس : 10. وَإِذا تُتْلى عَلَيْهِمْ آياتُنا قالُوا قَدْ سَمِعْنا لَوْ نَشاءُ لَقُلْنا مِثْلَ هذا إِنْ هذا إِلاَّ أَساطِيرُ الْأَوَّلِينَ (31) وَإِذْ قالُوا قلتم : نخرجه من بلادنا ؟ فقد خرج عنكم فأقبلوا يضربونه ويقولون : أنت تخدعنا منذ الليلة ، فتفرقوا في الجبال وكان فيهم رجل من خزاعة يقال له أبو كرز يقفوا الآثار ، فقالوا : يا أبا كرز اليوم اليوم ، فوقف بهم على باب حجرة رسول الله صلى‌الله‌عليه‌وآله‌وسلم فقال : هذه قدم محمد والله إنها لأخت القدم التي في المقام ، فما زال بهم حتى أوقفهم على باب الغار ثم قال : ما جاوزوا هذا المكان ، إما أن يكون صعد إلى السماء أو دخل تحت الأرض ، وقد كان بعث الله العنكبوت فنسجت على باب الغار وجاء فارس من الملائكة حتى وقف على باب الغار ثم قال : ما في الغار أحد ، فتفرقوا في الشعاب وصرفهم الله عن رسوله ثم أذن له بالهجرة (1) .` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ", tafsir: `` },
            { text: "وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ", tafsir: `` },
            { text: "وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ", tafsir: `قد كان بعض الكفار ( إِذا تُتْلى عَلَيْهِمْ آياتُنا ) من القرآن الحكيم ( قالُوا قَدْ سَمِعْنا ) بآذاننا ( لَوْ نَشاءُ لَقُلْنا مِثْلَ هذا ) المسموع ، فإن العاجز المتكبر دائما يظهر القدرة ، لكنه لا يظهر منه الأثر بخلاف القادر المتواضع الذي يعمل كثيرا ويقول قليلا ( إِنْ هذا ) أي ما هذا القرآن ( إِلَّا أَساطِيرُ الْأَوَّلِينَ ) جمع « أسطورة » ، والمراد بها : أخبار الماضين ومختلقاتهم. قالوا : وقد كان قائل هذا النضر بن الحارث ابن كلدة وقد أسر يوم بدر وقتل.` },
            { text: "وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ", tafsir: `اذكر يا رسول الله ( إِذْ قالُوا ) أي بعض الكفار وهو أبو ( 1) راجع بحار الأنوار : ج 19 ص 50. اللهُمَّ إِنْ كانَ هذا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنا حِجارَةً مِنَ السَّماءِ أَوِ ائْتِنا بِعَذابٍ أَلِيمٍ (32) جهل : ( اللهُمَّ إِنْ كانَ هذا ) الذي جاء به محمد ( هُوَ الْحَقَّ مِنْ عِنْدِكَ ) وكنا نحن على الباطل ( فَأَمْطِرْ عَلَيْنا حِجارَةً ) المراد بها « جنس الحجارة » وليست « التاء » للمفرد ( مِنَ السَّماءِ ) أي من جهة العلو ، كما أمطرت على قوم لوط ( أَوِ ائْتِنا ) أي صبّ علينا وجئنا ( بِعَذابٍ أَلِيمٍ ) مؤلم. فقد روي أن النبي صلى‌الله‌عليه‌وآله‌وسلم قال : أجيبوني إلى ما أدعوكم إليه تملكون بها العرب وتدين لكم العجم. فقال أبو جهل : « اللهم إن كان هذا هو الحق فأمطر علينا حجارة من السماء أو ائتنا بعذاب أليم » (1) . و في بعض الروايات : أنها نزلت حين نصب الرسول عليّا خليفة له يوم غدير خم ، فجاءه رجل يقال له الحارث بن عمرو الفهري فحاجّ النبي في شأن علي عليه‌السلام ثم سأله : هل هذا من الله أو منك ؟ فقال النبي صلى‌الله‌عليه‌وآله‌وسلم : بل من الله سبحانه. فأخذ يذهب وهو يدعو بهذا الدعاء « اللهم إن كان .. الى آخره » ، حسدا وبغضا للإمام عليه‌السلام . فقال له النبي صلى‌الله‌عليه‌وآله‌وسلم : إما تبت وإما رحلت ، فركب راحلته وخرج ، ولما وصل إلى خارج المدينة أتته جندلة فرضّت هامته ، وفيه نزلت : ( سَأَلَ سائِلٌ بِعَذابٍ واقِعٍ ) (2) ، فقال النبي صلى‌الله‌عليه‌وآله‌وسلم لبعض المنافقين : انطلقوا إلى صاحبكم فقد أتاه ما استفتح به (3) . ( 1) بحار الأنوار : ج 18 ص 158. ( 2) المعارج : 2. ( 3) راجع بحار الأنوار : ج 35 ص 323. وَما كانَ اللهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَما كانَ اللهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ (33) وَما لَهُمْ أَلاَّ يُعَذِّبَهُمُ اللهُ أقول : وكأن النبي صلى‌الله‌عليه‌وآله‌وسلم أمره بالرحيل حتى لا يمنع عن عذابه وجوده صلى‌الله‌عليه‌وآله‌وسلم عنده حيث قال سبحانه : ( وَما كانَ اللهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ ) . كما أنه لا منافاة بين الحديثين ، فقد كانت بعض آي القرآن وسوره ينزل مرتين وأكثر ، فلعلها نزلت مرة في قصة أبي جهل ومرة في قصة الحارث. [34] ثم بيّن سبحانه أنهم مع استحقاقهم العذاب لما كانوا يفعلونه ، لكنه لا يعجّل لهم ما دام الرسول صلى‌الله‌عليه‌وآله‌وسلم فيهم ، فلعلهم يرجعون ويتوبون ، وما دام أنهم ـ مع كفرهم ـ يستغفرون الله سبحانه ، كما روي أن أبا جهل بعد ما ذكر الدعاء قال : واستغفر الله ، فقال سبحانه : ( وَما كانَ اللهُ لِيُعَذِّبَهُمْ ) بإمطار الحجارة عليهم ـ كما طلبوا ـ أو غيره ( وَأَنْتَ فِيهِمْ ) جملة حالية ، أي : في حال كونك يا رسول الله بين أظهرهم ، والمراد بذلك إما الرحمة بهم لأجلك ، أو عدم عذابهم لاحتمال الإيمان ، فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم ما دام فيهم يحتمل رجوعهم وهدايتهم. ( وَما كانَ اللهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ ) ولعل اختلاف التعبير في « ليعذبهم » و « معذبهم » لأجل أن كون الرسول صلى‌الله‌عليه‌وآله‌وسلم بين أظهرهم له أمد ولذا جاء بالفعل ، أما الاستغفار فإنه لا مدة له ولذا جيء بالاسم الدال على الدوام. [35] ثم بيّن سبحانه أنه وإن كان لا يعذبهم إلّا أنهم يستحقون العذاب بما يرتكبون من الآثام ، فقال سبحانه : ( وَما لَهُمْ أَلَّا يُعَذِّبَهُمُ اللهُ ) أي لم لا يعذبهم وأي أمر يوجب ترك تعذيبهم وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرامِ وَما كانُوا أَوْلِياءَهُ إِنْ أَوْلِياؤُهُ إِلاَّ الْمُتَّقُونَ وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ (34) ( وَ ) الحال أن ( هُمْ يَصُدُّونَ ) ويمنعون الناس المؤمنين ( عَنِ الْمَسْجِدِ الْحَرامِ ) فقد أخرجوا الرسول صلى‌الله‌عليه‌وآله‌وسلم والمؤمنين ، وأجبروهم إلى الهجرة نحو الحبشة والطائف والمدينة ( وَ ) الحال أنهم ( ما كانُوا أَوْلِياءَهُ ) أي أولياء المسجد ، أي لم يكن المشركون أصحاب ولاية على المسجد الحرام حتى يكون الصدّ عنه مشروعا ، فإنهم حيث كفروا برب المسجد وخالفوا أوامره لوضع الأصنام فيه وهتكوا حرمته بالتصفيق فيه ، لم تكن لهم ولاية عليه ( إِنْ أَوْلِياؤُهُ إِلَّا الْمُتَّقُونَ ) أي ليس أولياء المسجد إلّا الذين يتقون الله سبحانه ويطيعون أوامره وهم المؤمنون ، فإنهم أولياؤه الشرعيون ( وَلكِنَّ أَكْثَرَهُمْ ) أي أكثر هؤلاء المشركين ( لا يَعْلَمُونَ ) ذلك ويظنون ـ حيث أنهم ورثوا سدانة البيت من آبائهم ـ أنهم بذلك يكونون أولى بالمسجد. ورد في حديث عن الإمام أمير المؤمنين عليه‌السلام أنه قال : « كان في الأرض أمانان من عذاب الله ، وقد رفع أحدهما ، فدونكم الآخر ، فتمسكوا به » (1) . وقرأ الآية : ( وَما كانَ اللهُ لِيُعَذِّبَهُمْ .. . ) . [36] ثم بيّن سبحانه علّة عدم كونهم أولياء المسجد ، وذلك لأن صلاتهم هتك لحرمته وإنفاقهم لأجل الصدّ عنه ، وهل يكون وليّ شيء هاتكا ( 1) بحار الأنوار : ج 90 ص 284. وَما كانَ صَلاتُهُمْ عِنْدَ الْبَيْتِ إِلاَّ مُكاءً وَتَصْدِيَةً فَذُوقُوا الْعَذابَ بِما كُنْتُمْ تَكْفُرُونَ (35) إِنَّ الَّذِينَ كَفَرُوا يُنْفِقُونَ أَمْوالَهُمْ لِيَصُدُّوا عَنْ سَبِيلِ اللهِ فَسَيُنْفِقُونَها ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً وصادا عنه ؟ ( وَما كانَ صَلاتُهُمْ ) أي دعاء المشركين وعبادتهم ( عِنْدَ الْبَيْتِ ) الحرام ( إِلَّا مُكاءً وَتَصْدِيَةً ) « المكاء » الصفير ، يقال : « مكا يمكو مكاء » إذا صفّر بفيه. و « التصدية » التصفيق ، وهو ضرب اليد على اليد. فقد كان المشركون يطوفون بالبيت عراة يصفرون ويصفقون. و في حديث : أن النبي صلى‌الله‌عليه‌وآله‌وسلم كان إذا صلّى قام رجلان من بني عبد الدار عن يمينه فيصفران ، ورجلان عن يساره يصفقان بأيديهما فيخلطان عليه صلاته ، وقد قتلوا جميعا يوم بدر (1) . ( فَذُوقُوا ) أيها الكفار ( الْعَذابَ ) في الدنيا بالقتل والأسر وغيرهما ، وفي الآخرة في نار حرّها شديد بسبب ما ( كُنْتُمْ تَكْفُرُونَ ) بالله ورسوله.` },
            { text: "وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ", tafsir: `` },
            { text: "وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ", tafsir: `في قتال الرسول والمؤمنين والتأليف عليهم ( لِيَصُدُّوا عَنْ سَبِيلِ اللهِ ) أي يمنعوا الناس بذلك عن دين الله وطريقه المستقيم ، فكيف يمكن أن يكون الصاد عن سبيل الله وليا لمسجد الله ؟ ( فَسَيُنْفِقُونَها ) أي يقع منهم الإنفاق ( ثُمَّ تَكُونُ ) الأموال المنفقة للصد عن سبيل الله ( عَلَيْهِمْ حَسْرَةً ) موجبة للحزن ( 1) بحار الأنوار : ج 17 ص 87. ثُمَّ يُغْلَبُونَ وَالَّذِينَ كَفَرُوا إِلى جَهَنَّمَ يُحْشَرُونَ (36) لِيَمِيزَ اللهُ الْخَبِيثَ مِنَ الطَّيِّبِ وَيَجْعَلَ الْخَبِيثَ بَعْضَهُ عَلى بَعْضٍ فَيَرْكُمَهُ جَمِيعاً فَيَجْعَلَهُ فِي جَهَنَّمَ أُولئِكَ والتحسّر يخسرونها بلا جدوى ( ثُمَّ يُغْلَبُونَ ) في الدنيا بظفر المسلمين عليهم ، وفي الآخرة بأنها تسبب لهم النار ( وَالَّذِينَ كَفَرُوا إِلى جَهَنَّمَ يُحْشَرُونَ ) أي يجمعون ، فإنهم يجمعون كلهم هناك جزاء لما فعلوا من الكفر والعصيان. وفي بعض التفاسير : إن الآية نزلت فيما أنفقه الكفار يوم بدر لقتال المسلمين ، وقد أخبر الله عن العاقبة قبل وقوعها فكانت كما ذكر. [38] إن ما تقدم من إخلاء الله السبيل للكفار حتى ينفقوا أموالهم في سبيل الصدّ عن طريق الله سبحانه ( لِيَمِيزَ اللهُ الْخَبِيثَ مِنَ الطَّيِّبِ ) فتكون الأموال المنفقة في سبيل الله معلومة ، وتكون الأموال المنفقة في سبيل الباطل معلومة ، فقد كانت الأموال قبل الاحتكاك وحدوث الحادثة غير مميز خبيثها من طيبها ، أما في الحادثة فسيتميز بعضها عن بعض ( وَ ) ل ( يَجْعَلَ الْخَبِيثَ بَعْضَهُ عَلى بَعْضٍ ) فإنه كان متفرّقا في أموال عدة ، وبذلك تتجمع أجزاؤه ( فَيَرْكُمَهُ ) أي يجعله ركاما مجموعا ( جَمِيعاً ) كالنفايات والقاذورات التي تتجمع من البيوت ، ويجعل بعضها على بعض في المزبلة ( فَيَجْعَلَهُ فِي جَهَنَّمَ ) كما تجتمع القاذورات في المنافي خارج المدينة. وهذا من باب تشبيه المعقول بالمحسوس ليكون أوقع في النفس ( أُولئِكَ ) الذين أنفقوا هذه الأموال في سبيل هُمُ الْخاسِرُونَ (37) قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ ما قَدْ سَلَفَ وَإِنْ يَعُودُوا فَقَدْ مَضَتْ سُنَّتُ الْأَوَّلِينَ (38) وَقاتِلُوهُمْ حَتَّى لا تَكُونَ فِتْنَةٌ الباطل ( هُمُ الْخاسِرُونَ ) فقد خسروا الأموال ، بل اشتروا بها العار والنار.` },
            { text: "لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ", tafsir: `` },
            { text: "قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ", tafsir: `يا رسول الله ( لِلَّذِينَ كَفَرُوا ) لا تيأسوا من رحمة الله ، فإن الإنسان مهما عصى ، إذا تاب ؛ تاب الله عليه ( إِنْ يَنْتَهُوا ) عن كفرهم وعصيانهم ، بالإسلام والطاعة ( يُغْفَرْ لَهُمْ ما قَدْ سَلَفَ ) من ذنوبهم ومعاصيهم ( وَإِنْ يَعُودُوا ) إلى كفرهم وأعمالهم ، و « العودة » باعتبار أن كل يوم كفر جديد ومعصية جديدة ( فَقَدْ مَضَتْ سُنَّتُ الْأَوَّلِينَ ) أي عادة الله فيهم بالإهلاك ، فإنها تنطبق على هؤلاء ، وإضافة السنة إلى الأولين ، باعتبار كون سنة الله واقعة عليهم ، ويكفي في الإضافة أدنى ملابسة ـ كما ذكروا ـ ويحتمل أن يكون المراد : إن ينتهوا عن قتال الرسول صلى‌الله‌عليه‌وآله‌وسلم تركوا وشأنهم ولم يعاقبهم الرسول بما فعلوا ـ فهو مغفرة لهم ـ وإن عادوا إلى القتال فقد مضت سنة الله في الأنبياء أن يكون المحاربون هم المغلوبون المنهزمون ، وهذا تهديد إلى كل من تسوّل له نفسه قتال الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ", tafsir: `أي قاتلوا الكفار أيها المسلمون ( حَتَّى لا تَكُونَ فِتْنَةٌ ) أي لا توجد فتنة ـ فإن « كان » تامة ـ فإن الكفار مهما وجدوا القوة والمنعة فتنوا المؤمنين عن دينهم ، وأحدثوا الفتن والقلاقل ، أما إذا قوتلوا وكسرت شوكتهم ، ذهبت الفتن وتحطمت المؤامرات والمكايد وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ فَإِنِ انْتَهَوْا فَإِنَّ اللهَ بِما يَعْمَلُونَ بَصِيرٌ (39) وَإِنْ تَوَلَّوْا فَاعْلَمُوا أَنَّ اللهَ مَوْلاكُمْ نِعْمَ الْمَوْلى وَنِعْمَ النَّصِيرُ (40) ( وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ ) المراد ب « الدين » الطريقة ، أي حتى تتجمع الطرائق على طريقة واحدة ، هي طريقة الله سبحانه. وهذه الآية تدل على جواز المقاتلة إلى أن تتوحد الطرائق في طريقة ارتضاها الله سبحانه للعباد ، فلا يكون دين سواه ( فَإِنِ انْتَهَوْا ) أي انتهى هؤلاء الكفار عن الكفر والعصيان ومحاربة الرسول والمؤمنين ( فَإِنَّ اللهَ بِما يَعْمَلُونَ بَصِيرٌ ) فإنه يعلم السر وأخفى. وما على المسلمين إلّا توحيد الصفوف ظاهرا أما البواطن والسرائر فليس عليهم ، بل الله يعلم بها ويجازي كل واحد حسب ضميره وسرّه.` },
            { text: "وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ", tafsir: `أي أعرض الكفار عن الإيمان ، ولم ينتهوا عن الكفر والعصيان ( فَاعْلَمُوا ) أيها المؤمنون ( أَنَّ اللهَ مَوْلاكُمْ ) سيّدكم وناصركم ، فلا تخشوهم ، بل أقدموا على محاربتهم ، فالله ( نِعْمَ الْمَوْلى ) حيث أنه عالم قادر وفيّ بما يعد ( وَنِعْمَ النَّصِيرُ ) لا يغلبه أحد كما قال سبحانه : ( إِنْ يَنْصُرْكُمُ اللهُ فَلا غالِبَ لَكُمْ ) (1) . ( 1) آل عمران : 161. تقريب القران الى الأذهان من آية 42 من سورة الأنفال إلى آية 93 من سورة التوبة بسم الله الرّحمن الرّحيم الحمد لله رب العالمين والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين وَاعْلَمُوا أَنَّما غَنِمْتُمْ مِنْ شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبى وَالْيَتامى وَالْمَساكِينِ وَابْنِ السَّبِيلِ [42] وحيث سبق الكلام حول قصة بدر ، يعود السياق ليذكر جوانب أخرى من القصة كما هو عادة القرآن الحكيم ، حيث يبيّن من القصة جوانب معينة فقط ، ثم يبيّن تلك الجوانب في ثنايا آيات أخرى ، لتبقى للقصة ظرافتها ، ولئلّا تكون مملّة ككتب التاريخ التي تسرد القصص ، ولأن يكون للنفس شوق وتلهف إلى القرآن وإلى القصة يسوقان الإنسان إلى التملّي منها. وتبتدئ بذكر الغنيمة والحكم فيها ، كما ابتدأت السورة بذكرها في الجملة فقال سبحانه : ( وَاعْلَمُوا ) أيها المسلمون ( أَنَّما غَنِمْتُمْ مِنْ شَيْءٍ ) والغنيمة : هي الفائدة مطلقا سواء حصلت من الحرب أو من غيرها ، وإن كان مورد نزول الآية غنائم دار الحرب ، وكلمة « من شيء » للتأكيد ، أي سواء كانت الغنيمة قليلة أو كثيرة ( فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبى ) أي قرابة الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وهو الإمام عليه‌السلام ، فالنصف من الخمس أي عشرة من المائة منه للإمام عليه‌السلام ، إذ حصة الله سبحانه للرسول وحصة الرسول للإمام ، وفي حال الغيبة يدفع هذا النصف إلى نواب الإمام وهم الفقهاء الجامعون للشرائط ، وهم يصرفونه في ترويج الإسلام ، حيث قال الإمام عليه‌السلام : « إن الخمس عوننا على ديننا » (1) . وإنما ذكر « الله » سبحانه تعظيما لأمر الرسول والإمام واحتراما لهما ، حيث قرنا به ، وإلّا فالأموال كلها لله سبحانه ( وَ ) النصف الآخر من الخمس ل ( الْيَتامى وَالْمَساكِينِ وَابْنِ السَّبِيلِ ) ممن ينتهي نسبه ( 1) الكافي : ج 1 ص 547. إِنْ كُنْتُمْ آمَنْتُمْ بِاللهِ وَما أَنْزَلْنا عَلى عَبْدِنا يَوْمَ الْفُرْقانِ يَوْمَ الْتَقَى الْجَمْعانِ وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ (41) إلى هاشم جدّ الرسول صلى‌الله‌عليه‌وآله‌وسلم من السادة. ويشترط في هؤلاء الفقر ، وقد عوّضهم الله عن الزكاة التي جعلت لغير السادة ـ إذا كانت من غير السادة ـ ثم أن الأربعة أخماس الباقية من الغنيمة ، تقسم بين المقاتلين في غنائم دار الحرب ، ولصاحب المال في خمس سائر الغنائم ، فإن الخمس يجب في سبعة أشياء : غنائم دار الحرب ، والمكاسب مطلقا ، والغوص ، والكنز ، والمعدن ، والحلال المختلط بالحرام ، والأرض المنتقلة إلى الذمي ( إِنْ كُنْتُمْ آمَنْتُمْ بِاللهِ ) أي لا تطمعوا في كل الغنيمة إن كنتم آمنتم بالله ، فهو متعلق بقوله « واعلموا » وليس مفهوم الشرط : أن الخمس ليس لهؤلاء إن لم تكونوا آمنتم ، بل مفهومه إن كنتم آمنتم تؤمنون بذلك. ( وَ ) إن كنتم آمنتم ب ( ما أَنْزَلْنا عَلى عَبْدِنا ) يعني الرسول صلى‌الله‌عليه‌وآله‌وسلم ( يَوْمَ الْفُرْقانِ ) أي يوم فرقنا بين الحق والباطل وهو يوم بدر ( يَوْمَ الْتَقَى الْجَمْعانِ ) جمع المؤمنين من أصحاب الرسول وجمع الكافرين من أهل مكة للقتال ، والمراد ب « ما أنزلنا » الملائكة أو النصر ، إي : إن كنتم مؤمنين بالله وبما أنزل من النصر والملائكة على الرسول يوم بدر ، تؤمنون بهذا الحكم الذي هو كون الخمس للطوائف الستة المذكورين وليس للمقاتلين فيه حق ( وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فيقدر أن ينصر الجماعة القليلة على الجماعة الكثيرة. [43] إن المسلمين خرجوا من المدينة لإدراك قافلة أبي سفيان التجارية فنزلوا بضفة الوادي القريبة من المدينة ونزل جيش المشركين ـ الذين إِذْ أَنْتُمْ بِالْعُدْوَةِ الدُّنْيا وَهُمْ بِالْعُدْوَةِ الْقُصْوى وَالرَّكْبُ أَسْفَلَ مِنْكُمْ جاءوا من مكة لإنقاذ القافلة ـ بقيادة أبي جهل على الضفة الأخرى البعيدة من المدينة ، وبين الفريقين ربوة ، أما القافلة فقد مال بها أبو سفيان إلى سيف البحر أسفل من الجيش ، ولم يكن كلا الجيشين يعلم بموقع الجيش الآخر حتى أنه لو كان بينهما موعد للقاء لم يجتمعا بهذه الكيفية ولكن الله جمعهما على جانبي الربوة لينصر المسلمين على الكفار ويرى الجميع من الدلائل الباهرة ما يكفي لإتمام الحجة ، وقد رأى الرسول صلى‌الله‌عليه‌وآله‌وسلم في الرؤيا جيش المشركين قليلا فأخبر أصحابه بذلك ، فاستبشروا وتشجعوا وأقدموا على القتال ، ولو رآهم كثيرا وأخبر أصحابه بذلك لخافوا ووجلوا فيفشلوا ، ولم تكن الرؤيا كاذبة فإنهم بعددهم الكثير كانوا قليلا في الواقع بالنسبة إلى قواهم المعنوية الضئيلة. والقرآن الحكيم يبيّن هذا الطرف من القصة بقوله سبحانه : ( إِذْ أَنْتُمْ ) « إذ » متعلق بقوله : ( وَما أَنْزَلْنا عَلى عَبْدِنا ) أي أن إنزالنا كان في وقت كنتم أيها المسلمون ( بِالْعُدْوَةِ الدُّنْيا ) مؤنث « أدنى » أي العدوة القريبة من المدينة ، و « العدوة » شفير الوادي ، فإن لكل وادي عدوتان أي جانبان ( وَهُمْ ) أي الكفار ( بِالْعُدْوَةِ الْقُصْوى ) مؤنث « الأقصى » بمعنى البعيدة ، أي في الطرف البعيد من الوادي ، وبعده باعتبار المدينة المنورة ( وَالرَّكْبُ ) أي قافلة قريش التجارية ، وهو جمع « راكب » ، كصاحب وصحب ( أَسْفَلَ مِنْكُمْ ) أي في مكان أسفل منكم إلى جانب البحر ، وليس المراد ب « الأسفل » الانخفاض بل الأبعد. وَلَوْ تَواعَدْتُمْ لاخْتَلَفْتُمْ فِي الْمِيعادِ وَلكِنْ لِيَقْضِيَ اللهُ أَمْراً كانَ مَفْعُولاً لِيَهْلِكَ مَنْ هَلَكَ عَنْ بَيِّنَةٍ وَيَحْيى مَنْ حَيَّ عَنْ بَيِّنَةٍ والفائدة في ذكر هذه المواطن الإخبار الدال على قوة المشركين وضعف المسلمين وإن غلبتهم في مثل هذه الحالة كان بأمر إلهي وذلك أن العدوة القصوى كان فيها الماء ولا ماء بالعدوة الدنيا ، وكانت رخوة تسوخ فيها الأرجل وكانت العير وراء ظهورهم مع كثرة عددهم فكانت الحماية دونها تضاعف حميتهم وتحملهم على أن لا يبرحوا مواطنهم ويبذلون نهاية جهدهم ، ومع ذلك فقد نصر الله المسلمين. ( وَلَوْ تَواعَدْتُمْ ) أنتم والكفار على اللقاء في مكان واحد ( لَاخْتَلَفْتُمْ فِي الْمِيعادِ ) فإنكم كنتم تخافونهم لكثرتهم واستعدادهم ، وهم كانوا يخافونكم لشدة بطشكم ، وما أدخل في قلوبهم من الرعب منكم ، فقد كانت أسباب عدم القتال ، أو القتال بهزيمتكم متوفرة ( وَلكِنْ ) شاء الله سبحانه وقدّر أن يجمعكم بهذه الكيفية وينصركم عليهم ( لِيَقْضِيَ اللهُ أَمْراً ) أي ينفذه ويأتي به إلى الوجود ( كانَ مَفْعُولاً ) أي واجبا أن يفعل ومقدرا أن يكون ، فقد قضى سبحانه إعزاز الإسلام ونصرة المسلمين. وإنما قضى ذلك ( لِيَهْلِكَ مَنْ هَلَكَ عَنْ بَيِّنَةٍ ) أي ليموت من يموت من الكافرين بعد تمام الحجة عليه ، فإن نصر المسلمين بتلك الكيفية كان من البراهين الدالة على صدق الرسول صلى‌الله‌عليه‌وآله‌وسلم فمن لم يؤمن بعد ذلك ومات ، كان هلاكه بعد إتمام الحجة عليه ( وَيَحْيى مَنْ حَيَّ عَنْ بَيِّنَةٍ ) أي يعيش من عاش منهم بعد إتمام الحجة عليه ، وهذا كما وَإِنَّ اللهَ لَسَمِيعٌ عَلِيمٌ (42) إِذْ يُرِيكَهُمُ اللهُ فِي مَنامِكَ قَلِيلاً وَلَوْ أَراكَهُمْ كَثِيراً لَفَشِلْتُمْ وَلَتَنازَعْتُمْ فِي الْأَمْرِ وَلكِنَّ اللهَ سَلَّمَ إِنَّهُ عَلِيمٌ بِذاتِ الصُّدُورِ يقال : « أتممت الحجة على الأحياء والأموات » ، أو المراد من « الهلاك والحياة » الكفر والإسلام ، فقد تقدم أن الحياة الكاملة في الإسلام ، كما أن الكافر ليس إلا ميتا في كثير من الأمور الحيوية ، ولذا يقال عن المؤمن أنه حي ، وعلى الكافر أنه ميت ، كما قال سبحانه : ( اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذا دَعاكُمْ لِما يُحْيِيكُمْ ) (1) ، ( وَإِنَّ اللهَ لَسَمِيعٌ ) لأقوالكم ( عَلِيمٌ ) بضمائركم ، فإن الحرب غالبا مثار كلام غير لائق ونيات سيئة ، ولذا يذكّرهم سبحانه بوجوب حفظ الألسنة والضمائر عن السوء. [44] وقد ذكر ما تقدم من نزول النصر ( إِذْ يُرِيكَهُمُ ) أي يريك ( اللهُ ) الكفار ( فِي مَنامِكَ ) يا رسول الله ( قَلِيلاً ) لتخبر بذلك المؤمنين فتقوى قلوبهم ( وَلَوْ أَراكَهُمْ كَثِيراً ) أي أراك الله الكفار كثيرا ، ثم أخبرت بذلك المؤمنين ( لَفَشِلْتُمْ ) أيها المؤمنون وضعفت عزيمتكم في قتالهم ، فإن الفشل هو الضعف عن فزع وخوف ( وَلَتَنازَعْتُمْ فِي الْأَمْرِ ) أي في أمر محاربتهم حيث كنتم ترهبونهم ، فيقول بعضكم : نقاتلهم ، ويقول بعض : لا نقاتلهم ( وَلكِنَّ اللهَ سَلَّمَ ) أي سلّم المؤمنين عن الفشل والتنازع واختلاف الكلمة ( إِنَّهُ ) سبحانه ( عَلِيمٌ بِذاتِ الصُّدُورِ ) أي بما يدور في صدور الناس من الوساوس وتقلّب ( 1) الأنفال : 25. (43) وَإِذْ يُرِيكُمُوهُمْ إِذِ الْتَقَيْتُمْ فِي أَعْيُنِكُمْ قَلِيلاً وَيُقَلِّلُكُمْ فِي أَعْيُنِهِمْ وجوه الرأي. وقد ذكرنا أن « الإراءة قليلا » لم تكن كذبا بل باعتبار أن الإنسان القوي دائما يرى الكثير قليلا ، بخلاف الإنسان الجبان الذي يرى القليل كثيرا ، هذا بالإضافة إلى أنه محسوس مجرّب ، مبسوط في علم النفس ومشروح. [45] وحيث تقابل الجيشان رأى المسلمون قلّة المشركين ، لما كانوا يحملونه من القوة في نفوسهم والتصميم والإرادة بتسديدهم وعزمهم ، ورأى المشركون قلة المسلمين حيث كانوا قليلا عددا ، فإن المسلمين كانوا ثلاثمائة وثلاث عشر بينما كان الكافرون بين التسعمائة والألف ، وحيث كان كل فريق يرى خصمه قليلا تجرّأ الطرفان على القتال مما أدى إلى نصر المسلمين ( وَإِذْ يُرِيكُمُوهُمْ ) أي يريكم الله أيها المؤمنون ، الكافرين ( إِذِ الْتَقَيْتُمْ ) أي في زمان لقائكم وإياهم في ساحة القتال ( فِي أَعْيُنِكُمْ ) أي في نظركم ( قَلِيلاً ) فكان الكفار في نظر المسلمين قليلين لما عندهم من الإرادة والقوة. ومن المعلوم أن الحالات النفسية تؤثر في حواس الإنسان الظاهرة ، وقد كان هذا بإرادة الله سبحانه حيث قوّى نفوس المسلمين حتى يروا الكافرين قليلين فيطمعوا فيهم ( وَيُقَلِّلُكُمْ ) أيها المؤمنون ( فِي أَعْيُنِهِمْ ) أي أعين الكافرين ، فقد أراد الله سبحانه أن يقلل المؤمنين في نظر الكافرين لئلّا ينسحبوا عن قتالهم ، فلا ينال المؤمنون منهم نيلا ، وقد كان ذلك سبب غرور الكافرين فقد كان أبو جهل يقول لأصحابه : خذوا المسلمين بالأيدي أخذا ولا تقاتلوهم. لِيَقْضِيَ اللهُ أَمْراً كانَ مَفْعُولاً وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ (44) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا لَقِيتُمْ فِئَةً فَاثْبُتُوا وَاذْكُرُوا اللهَ كَثِيراً لَعَلَّكُمْ تُفْلِحُونَ (45) وإنما فعل ذلك سبحانه ، بأن قلّل كل جانب في نظر الجانب الآخر ( لِيَقْضِيَ اللهُ أَمْراً كانَ مَفْعُولاً ) أي ينفذ إرادته في غلبة المسلمين ، التي كانت قد قدّرت. وقد كررت هذه الجملة تأكيدا ، ولإفادة أن النصر كما كان من عند الله ، كان التقليل من عنده أيضا ( وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ ) فإن الأمور كما كانت بقدر الله وقضائه ، كذلك تكون مصائر الأمور إليه ، فبيده المبدأ والمعاد ، وهذا التشجيع للمسلمين في أن يقدموا ، فإن المبدأ والمنتهى بيد ناصرهم ومعينهم وهو الله سبحانه. [46] وحيث بيّن سبحانه كيف أنه نصر المؤمنين في موقعة بدر مع كون القوى المادية كانت بجانب الكافرين ، أمر المسلمين أن يثبتوا أمام كل مشكلة ، فإن الله بجانبهم دائما ( يا أَيُّهَا الَّذِينَ آمَنُوا إِذا لَقِيتُمْ فِئَةً ) كافرة أو مخالفة ، ممن عتي عن أمر الله سبحانه ( فَاثْبُتُوا ) ولا تنهزموا أمامهم ، فإن الثبات يوجب النصر ، وبالعكس الانهزام والفرار يوجبان الفشل والخسران ( وَاذْكُرُوا اللهَ كَثِيراً ) مستعينين به في الحرب والدعوة ، فإن ذكر الله سبحانه يشجّع الإنسان ويقوّي فيه العزيمة ، كيف والإنسان بتكرار الذكر ، تتكون فيه ملكة الاتصال بالقوى الكونية ، هذا بالإضافة إلى أن نصرة الله سبحانه توجب قوة وطاقة خارقة في النفس ، كما ثبت في علم النفس ( لَعَلَّكُمْ تُفْلِحُونَ ) أي لكي تنجحوا وتظفروا وتفوزوا بخير الدنيا والآخرة. وَأَطِيعُوا اللهَ وَرَسُولَهُ وَلا تَنازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ وَاصْبِرُوا إِنَّ اللهَ مَعَ الصَّابِرِينَ (46)` },
            { text: "وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `` },
            { text: "إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَٰدِ وَلَٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ", tafsir: `` },
            { text: "إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `` },
            { text: "وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ", tafsir: `` },
            { text: "وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ وَٱصْبِرُوٓا۟ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ", tafsir: `فيما أمركم ( وَرَسُولَهُ ) فيما بيّن لكم ـ وقد مرّ مكررا أن قرن اسم الرسول باسم الله سبحانه للتعظيم ، ولأنه صلى‌الله‌عليه‌وآله‌وسلم هو المبيّن ـ ( وَلا تَنازَعُوا ) فيما بينكم فيقول بعض : نقدم ، ويقول بعض : نحجم ( فَتَفْشَلُوا ) فإن التنازع يوجب تبديد القوى المعنوية بالإضافة إلى تبديده وإضاعته للقوى المادية ( وَتَذْهَبَ رِيحُكُمْ ) أي دولتكم ، فإن الريح بمعنى الدولة لغة ، أو هو من باب التشبيه ، فإن الدولة تشبّه بالريح لهبوبها وسيطرتها على الأشياء ونفوذ أمرها ، يقال : « هبت ريح فلان » إذا نفذ أمره. والتنازع ، لا يجزئ القوى إلى سلب وإيجاب فقط ، بل فوق ذلك يضعف القوى الإيجابية. فلو فرضنا أن طاقة زيد تقدّر بألف مقاتل ، فإذا خالفه عمرو قدّرت طاقته بخمسمائة ، حتى أنه لو كان وحده بدون مخالف لقدرت طاقته بألف ، وذلك لأن المخالف يحدّ من النشاط ويضعف من القوى ، بخلاف التجمع فإنه يزيد الطاقة الألفية إلى الألفين. ولذا ثبت في علم النفس أن الإنسان إذا رأى خلافا فالأفضل أن يصمّ عن المخالف حتى يبقى على قواه الذاتية ، ولا تحد من نشاطه الطاقة المناوئة. ( وَاصْبِرُوا ) والفرق بين الثبات والصبر ، أن الصبر يلائم حالة الهزيمة والنصر ، وهو مقابل الجزع ، والثبات مقابل الانهزام ، ومن الواضح أن الصابر يصل إلى مطلبه ولو انهزم وقتيا ( إِنَّ اللهَ مَعَ الصَّابِرِينَ ) بالنصر والظفر ، وليس المراد المعية الجسمية ، كما هو واضح. وَلا تَكُونُوا كَالَّذِينَ خَرَجُوا مِنْ دِيارِهِمْ بَطَراً وَرِئاءَ النَّاسِ وَيَصُدُّونَ عَنْ سَبِيلِ اللهِ وَاللهُ بِما يَعْمَلُونَ مُحِيطٌ (47)` },
            { text: "وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ", tafsir: `أيها المؤمنون ( كَالَّذِينَ خَرَجُوا مِنْ دِيارِهِمْ ) من أهل مكة ( بَطَراً ) « البطر » الخروج من موجب النعمة بالكفر ، من « بطر » يعني « شق » ، ومنه « البيطار » لأنه يشق اللحم بالمبضع ، فقد خرج الكفار من مكة بالمعازف والطبول ( وَرِئاءَ النَّاسِ ) فإنهم لما خرجوا ملئوا خوفا ورعبا من المسلمين ، ولكن خرجوا ليظهروا أنهم لا يبالون بالمسلمين ويظهروا شوكتهم ( وَيَصُدُّونَ عَنْ سَبِيلِ اللهِ ) هذا مقابل قولهم أنهم أولى بالبيت من المسلمين. والمراد ب « الصد » المنع عنه ، حيث كانوا يقفون دون تبليغ الأحكام ( وَاللهُ بِما يَعْمَلُونَ مُحِيطٌ ) إحاطة علم وقدرة فيجازيهم بما عملوا. قال ابن عباس : أنه لما رأى أبو سفيان أنه أحرز عيره ، أرسل إلى قريش أن ارجعوا ، فقال أبو جهل : والله لا نرجع حتى نرد بدرا ـ وكان بدر موسم من مواسم العرب يجتمع لهم بها سوق كل عام ـ فنقيم بها ثلاثا ننحر الجزور ونطعم الطعام ونسقي الخمور وتعزف علينا القيان وتسمع بنا العرب فلا يزالون يهابوننا أبدا (1) . وإلى هذا أشارت الآية الكريمة ، فإن المسلمين يجب أن يكونوا مؤدبين بآداب الله سبحانه حتى في حالة الحرب.` },
            { text: "وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ", tafsir: `بحار الأنوار : ج 19 ص 236. وَإِذْ زَيَّنَ لَهُمُ الشَّيْطانُ أَعْمالَهُمْ وَقالَ لا غالِبَ لَكُمُ الْيَوْمَ مِنَ النَّاسِ وَإِنِّي جارٌ لَكُمْ فَلَمَّا تَراءَتِ الْفِئَتانِ بشياطينه يهول بهم على أصحاب الرسول صلى‌الله‌عليه‌وآله‌وسلم وأقبلت قريش يقدمها إبليس معه الراية فنظر إليه رسول الله صلى‌الله‌عليه‌وآله‌وسلم فقال لأصحابه : غضوا أبصاركم وعضوا على النواجذ ولا تسلّوا سيفا حتى آذن لكم. ثم رفع يده إلى السماء فقال : « يا رب إن تهلك هذه العصابة لم تعبد ، وإن شئت لا تعبد ، لا تعبد » (1) ثم أصابه الغشي فسري عنه وهو يسلت العرق عن وجهه وهو يقول : هذا جبرائيل قد أتاكم في ألف من الملائكة مردفين. فنظروا فإذا بسحابة سوداء فيها برق لامع قد وقع على عسكر رسول الله صلى‌الله‌عليه‌وآله‌وسلم وقائل يقول : أقدم حيزوم ، أقدم حيزوم. وسمعوا قعقعة السلاح من الجو ونظر إبليس إلى جبرائيل فتراجع ورمى باللواء فأخذ منبه بن الحجاج بمجامع ثوبه ثم قال : ويلك يا سراقة تفت في أعضد الناس ، فركله إبليس ركلة في صدره وقال : إني بريء منكم. ( وَ ) قد كان ذلك ( إِذْ زَيَّنَ لَهُمُ الشَّيْطانُ أَعْمالَهُمْ ) أي في وقت حسّن الشيطان أعمال المشركين في نظرهم بأن شجّعهم على قتال المسلمين ، ويحتمل أن يكون « إذ » معمولا لفعل مقدّر هو « اذكر » ( وَقالَ ) الشيطان للكفار : ( لا غالِبَ لَكُمُ الْيَوْمَ مِنَ النَّاسِ ) أي لا يغلبكم أحد من الناس لكثرتكم وقوتكم فانهضوا لقتال المسلمين ـ في بدر ـ ( وَإِنِّي جارٌ لَكُمْ ) من الإجارة ، ناصر لكم على عدوّكم ( فَلَمَّا تَراءَتِ الْفِئَتانِ ) أي التقت ، فرقتا المسلمين والكافرين ( 1) بحار الأنوار : ج 19 ص 255. نَكَصَ عَلى عَقِبَيْهِ وَقالَ إِنِّي بَرِيءٌ مِنْكُمْ إِنِّي أَرى ما لا تَرَوْنَ إِنِّي أَخافُ اللهَ وَاللهُ شَدِيدُ الْعِقابِ (48) إِذْ يَقُولُ الْمُنافِقُونَ ( نَكَصَ ) الشيطان أي رجع ( عَلى عَقِبَيْهِ ) أي متقهقرا منهزما ، فإن الإنسان إذا أراد أن يتقهقر اعتمد على عقب رجليه ، وهذا تشبيه لإفادة الفرار مع الجبن ، فإن الجبان لا يدبر خوفا من أن يلحقه الطلب. ( وَقالَ ) الشيطان للكفار : ( إِنِّي بَرِيءٌ مِنْكُمْ ) فلا صلة بيننا ، ولا أفي بما ضمنت لكم من الإجارة والنصر ( إِنِّي أَرى ما لا تَرَوْنَ ) فقد رأى الشيطان الملائكة وكان يعرفهم ، وعلم أنه لا طاقة له بهم ، كما أن الملائكة كانت تعرف الشيطان ( إِنِّي أَخافُ اللهَ ) بأن يعذبني على أيدي الملائكة ( وَاللهُ شَدِيدُ الْعِقابِ ) لا يطاق عذابه. وفي بعض التفاسير : وإنما قام الشيطان بهذا العمل ـ أي تشجيع الكفار ـ لأن الله سبحانه شاء أن يخرجهم إلى حرب المسلمين ، فتنكسر شوكتهم وتذهب ريحهم ويتحطم كبرياؤهم. ومن الانهزامية المادية أن نأوّل هذه الآية كسائر الآيات المبينة لما وراء المادة ، بتأويلات لا تنافي الأمور المادية ، فإن التأويل إنما يصح إذا دل عقل أو نقل قطعي على خلاف الظاهر ، أما إذا لم يدل دليل ولم تكن هناك قرينة ، فأي مبرّر لأن نترك الظاهر بمجرد أنه يلائم الأمور المادية ، ولو فتح هذا الباب للزم أن نقول بذلك حتى في القرآن الحكيم نفسه ، إذ هو أيضا أمر خارج عن طوق المادة. [50] كان تزيين الشيطان للمشركين قتالهم مع المسلمين ( إِذْ يَقُولُ الْمُنافِقُونَ ) وَالَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ غَرَّ هؤُلاءِ دِينُهُمْ وَمَنْ يَتَوَكَّلْ عَلَى اللهِ فَإِنَّ اللهَ عَزِيزٌ حَكِيمٌ (49) وَلَوْ تَرى إِذْ يَتَوَفَّى الَّذِينَ كَفَرُوا الْمَلائِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبارَهُمْ أي في حال صدور هذه المقالة عن المنافقين ، والمراد بهم إما الكفار ، فإن الكافر باعتبار أنه يعلم الواقع ويظهر خلافه يسمى منافقا ، وإما المسلمون المنافقون ( وَالَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ ) إما عطف بيان ، أو يراد أحد اللفظين المسلمون المنافقون ، وبالتالي الكفار ، والمراد بالمرض مرض الانحراف عن المنهج المستقيم ، فإن البدن كما يصاب بالأمراض الجسمية ، كذلك الروح تصاب بالأمراض الخلقية ، فالبخل والحسد والجبن وما أشبه أمراض ( غَرَّ هؤُلاءِ دِينُهُمْ ) أي غرّ المسلمين دينهم حتى خرجوا مع قلّتهم وصمّموا على قتال الكفار الأقوياء عددا وعدّة ( وَ ) ليس الأمر كذلك فإنه ( مَنْ يَتَوَكَّلْ عَلَى اللهِ ) فيسلم أمره إليه ويثق به ( فَإِنَّ اللهَ عَزِيزٌ ) لا يغلب ، وكذلك لا يغلب المتوكلون عليه ( حَكِيمٌ ) فيما يفعل ، يضع الأمور مواضعها ، فلا يترك المسلمين ولا يخذلهم ، بل ينصرهم على الكافرين ، فإنه له القوة يمنحها المتوكلين عليه ، وله الحكمة يدبّر بها الأمور. [51] إن الكافرين كان مبدأ أمرهم ـ في مقابلة المسلمين ـ الانهزام ، فلننظر إلى مصيرهم ( وَلَوْ تَرى ) يا رسول الله ، أو المراد كل من تتأتى منه الرؤية ( إِذْ يَتَوَفَّى الَّذِينَ كَفَرُوا الْمَلائِكَةُ ) أي تقبض الملائكة أرواح الكفار عند موتهم ( يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبارَهُمْ ) وَذُوقُوا عَذابَ الْحَرِيقِ (50) ذلِكَ بِما قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللهَ لَيْسَ بِظَلاَّمٍ لِلْعَبِيدِ (51) أي يضربونهم من الأمام ومن الخلف ، كما يضرب المجرم الكثير الاجرام ( وَ ) يقال لهم : ( ذُوقُوا عَذابَ الْحَرِيقِ ) أي العذاب الذي يحرق. و قد روي أن الملائكة كانت تضرب قتلى المشركين في بدر بالمقامع فتلهب جراحاتهم بالنار وتزهق أرواحهم (1) . والإتيان بصيغة الأمر في « ذوقوا » لتصوير المشهد كأنه مجسّم أمام المخاطب ، وهو من باب الإلفات ، كما ذكر في علم البلاغة.` },
            { text: "إِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ", tafsir: `` },
            { text: "وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ", tafsir: `` },
            { text: "ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ", tafsir: `العقاب لكم أيها الكفار ( بِما قَدَّمَتْ أَيْدِيكُمْ ) أي بما قدّمتم وفعلتم من الكفر والمعاصي ، وإنما نسب إلى اليد ، للتغليب ، فإن كثيرا من الأعمال تأتي بواسطة اليد ( وَأَنَّ اللهَ لَيْسَ بِظَلَّامٍ لِلْعَبِيدِ ) « ظلّام » صيغة للنسبة ، لا مبالغة ، كتمّار بمعنى المنسوب إلى التمر. قال ابن مالك : و مع فاعل ، وفعّال ، فعل في نسب أغنى عن اليا فقبل ومن المحتمل أن تكون مبالغة ، وذلك لإفادة أنه سبحانه لو كان ظالما لكان كثير الظلم لأن كل صفة تصحّ فيه تعالى لا بد وأن تبلغ شأنا كثيرا ، فنفي المبالغة نفي للأصل ، والمعنى : إن العقاب ليس إلا بسبب جناية العبد ، لا أنه اعتباطي منه سبحانه. ( 1) راجع مجمع البيان : ج 4 ص 480. كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِنْ قَبْلِهِمْ كَفَرُوا بِآياتِ اللهِ فَأَخَذَهُمُ اللهُ بِذُنُوبِهِمْ إِنَّ اللهَ قَوِيٌّ شَدِيدُ الْعِقابِ (52) ذلِكَ بِأَنَّ اللهَ لَمْ يَكُ مُغَيِّراً نِعْمَةً أَنْعَمَها عَلى قَوْمٍ حَتَّى يُغَيِّرُوا ما بِأَنْفُسِهِمْ` },
            { text: "كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ", tafsir: `الدأب : العادة ، والكافر للتشبيه ، أي أن عادة هؤلاء المشركين في الكفر بمحمد صلى‌الله‌عليه‌وآله‌وسلم ، كعادة آل فرعون وهم قومه وأتباعه ( وَالَّذِينَ مِنْ قَبْلِهِمْ ) من أقوام الأنبياء ، في الكفر بالرسل وتكذيبهم ، فليس تكذيب هؤلاء جديدا ، فإن السابقين عليهم أيضا ( كَفَرُوا بِآياتِ اللهِ ) وما أنزل على الأنبياء ( فَأَخَذَهُمُ اللهُ بِذُنُوبِهِمْ ) بأن عاقبهم وأنزل عليهم أنواع العذاب ( إِنَّ اللهَ قَوِيٌ ) لا يقدر أحد على التمرد عليه ، فإذا أراد أخذ أحد أخذه أخذ عزيز مقتدر ( شَدِيدُ الْعِقابِ ) وليس عقابه يسيرا هيّنا حتى لا يخشى منه.` },
            { text: "ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ", tafsir: `العقاب الذي حلّ بأولئك وهؤلاء ، ليس اعتباطا وابتلاء من الله سبحانه بلا استحقاق بل بسبب عملهم ، لأن ( اللهَ لَمْ يَكُ مُغَيِّراً نِعْمَةً أَنْعَمَها عَلى قَوْمٍ حَتَّى يُغَيِّرُوا ما ) أي الحالة الصحيحة التي كانت ( بِأَنْفُسِهِمْ ) إن الصحة والرخاء والأمن والغنى أحوال لاصقة بأنفس الناس ، منحها الله إياهم ، وطلب أن يعملوا برضاه فيها ، فإذا غيّروا ما طلب منهم بالنسبة إليها ، بأن صرفوا تلك النعم إلى المعاصي ، غيّر الله تلك النعم فأبدل الصحة مرضا ، والرخاء ضنكا ، والأمن اضطرابا ، والغنى فقرا. وهذا بالإضافة إلى كونه مرتبطا بما وراء المادة ، مرتبط بالمادة أيضا ، فإن الصحة تنحرف باستعمال وَأَنَّ اللهَ سَمِيعٌ عَلِيمٌ (53) كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِنْ قَبْلِهِمْ كَذَّبُوا بِآياتِ رَبِّهِمْ فَأَهْلَكْناهُمْ بِذُنُوبِهِمْ وَأَغْرَقْنا آلَ فِرْعَوْنَ المحرمات الضارة ، والرخاء ينحرف بعدم التعاون والعداء مما يسبب تفكك المجتمع فلا يزرع بمقدار ما كان التعاون يسببه ، وهكذا ، والأمن ينحرف إذا نوى كل إنسان الشر بأخيه ، والغنى ينحرف إذا كسل الناس عن العمل أو عملوا أعمالا غير مثمرة لا تفيد مالا. ومن المعلوم أنه لا يلزم أن يكون الناس مؤمنين ثم يكفرون ، بل هنالك مناهج بشرية عامة قرّرها سبحانه إذا سادت المجتمع كانوا في أمن ورفاه ، فإذا غيّروها تغيرت النعمة ، مثلا الظلم والقتل قبيحان ، والتعاون والإحسان حسنان ، أما بالنسبة إلى من بدّل الإيمان كفرا ومناهج الشريعة أهواء ، فذلك أوضح ( وَأَنَّ اللهَ سَمِيعٌ ) يسمع أقوال الناس ( عَلِيمٌ ) بضمائرهم ، فإذا رأى تغييرا في النيات ، وانحرافا في الكلمات غيّر ما أعطاهم من نعمة وما تفضّل عليهم من أمن وراحة.` },
            { text: "كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَكُلٌّ كَانُوا۟ ظَٰلِمِينَ", tafsir: `أي أن عادة هؤلاء الكفار كعادة آل فرعون ( وَالَّذِينَ مِنْ قَبْلِهِمْ ) من سائر الأمم. وإنما كرّر لتأكيد أن الحالة هي الحالة ، فإن كثيرا من الناس لا يصدقون أن ما جرى في الأمم السابقة تجري في هذه الأمة ، ولذا يحتاج الأمر إلى تركيز وتقرير ، وذلك لا يكون إلا بالتكرار والتذكير مرة فمرة ( كَذَّبُوا بِآياتِ رَبِّهِمْ ) دلائله وحججه ( فَأَهْلَكْناهُمْ بِذُنُوبِهِمْ ) فلم يموتوا ميتة طبيعية ، وإنما أخذوا بالعذاب ( وَأَغْرَقْنا آلَ فِرْعَوْنَ ) مع فرعون نفسه ، فإنه قد يطلق « الآل » على الأعم من الشخص وَكُلٌّ كانُوا ظالِمِينَ (54) إِنَّ شَرَّ الدَّوَابِّ عِنْدَ اللهِ الَّذِينَ كَفَرُوا فَهُمْ لا يُؤْمِنُونَ (55) الَّذِينَ عاهَدْتَ مِنْهُمْ ثُمَّ يَنْقُضُونَ عَهْدَهُمْ فِي كُلِّ مَرَّةٍ وَهُمْ لا يَتَّقُونَ (56) للتغليب ، كما تقدم في قوله : ( إِنَّ اللهَ اصْطَفى آدَمَ وَنُوحاً وَآلَ إِبْراهِيمَ ) (1) ، ( وَكُلٌ ) من تلك الأمم التي أهلكناهم ( كانُوا ظالِمِينَ ) وتخصيص الكلام بآل فرعون ، لأن كفرهم وعقوبتهم كانت ظاهرة واضحة لدى السامعين.` },
            { text: "إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ", tafsir: `الدابة : كل ما يدبّ على وجه الأرض ، لكن المنصرف منها الحيوان ، وشرّ الجميع ( عِنْدَ اللهِ ) في حكمه ( الَّذِينَ كَفَرُوا ) واستمروا على كفرهم ( فَهُمْ لا يُؤْمِنُونَ ) « الفاء » لعطف جملة على جملة. ولا يقال : إن الدواب لا شر فيها ، فكيف يجعل الكافر شرا منها ، لأنه يجاب عنه : بأن من الدواب ما فيها شر كالسامة والمؤذيات. والتي ليس فيها شر ، يعدّ شرا باعتبار أنها لا تهتدي طريقا ، وليس المراد بالشر هذا المعنى فقط. [57] ثم بيّن سبحانه المصداق الظاهر لذلك بقوله : الكفار ( الَّذِينَ عاهَدْتَ مِنْهُمْ ) عهد حسن الجوار بأن تكون في أمن منهم ، وهم في أمن منك ( ثُمَّ يَنْقُضُونَ عَهْدَهُمْ فِي كُلِّ مَرَّةٍ ) أي كلّما عاهدوا نقضوا العهد ولم يفوا به ( وَهُمْ لا يَتَّقُونَ ) الله ولا يخافون عقابه ، أو لا يتقون نقض العهد. والظاهر من الآية أن ذلك كان دأب بعض الكفار. وفي « المجمع » : عن مجاهد أنه أراد به يهود بني قريظة فإنهم قد ( 1) آل عمران : 34. فَإِمَّا تَثْقَفَنَّهُمْ فِي الْحَرْبِ فَشَرِّدْ بِهِمْ مَنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ (57) وَإِمَّا تَخافَنَّ عاهدوا النبي صلى‌الله‌عليه‌وآله‌وسلم على أن لا يضرّوا به ولا يمالئوا عليه عدوا ، ثم مالئوا عليه الأحزاب يوم الخندق وأعانوهم عليه بالسلاح ، وعاهدوا مرة بعد أخرى فنقضوا (1) . [58] وما هو جزاء هذه الفئة التي هي شرّ من الدواب ولا تلتزم حتى بالعهود ؟! ( فَإِمَّا تَثْقَفَنَّهُمْ ) « إن » الشرطية و « ما » زائدة ، و « ثقف » بمعنى : ظفر ، أي إن ظفرت بهم يا رسول الله ( فِي الْحَرْبِ فَشَرِّدْ بِهِمْ مَنْ خَلْفَهُمْ ) « التشريد » هو التفريق ، أي نكّل بهؤلاء تنكيلا وفرّقهم تفريقا حتى يتعثّر بهم من هم ورائهم من الذين عاهدوا معك ، حتى يخافوا فلا ينقضوا العهد. فتكون الآية دالّة على أمرين : الأول : تأديب هؤلاء الناقضين للعهد. الثاني : إلقاء الرعب في قلوب الآخرين لئلّا ينقضوا عهدهم ( لَعَلَّهُمْ ) أي لعلّ من خلفهم ( يَذَّكَّرُونَ ) أي يتذكرون أن نقض العهد يوجب مثل هذا التأديب فلا يقدموا على مثله ، فإن نقض العهد من أسوأ الأعمال ، إذ يدل ذلك على أن المعاهدة كانت للضعف ، فكلّما وجد أحد المعاهدين سبيلا إلى نقضه نقضه ، وهذا يوجب سقوط قيمة المعاهدات ، وأن لا يكون المتعاهدون بعضهم في أمن من بعض. أما الخدعة في الحرب فليست قبيحة إذ تلك بعد تأهّب كل فريق.` },
            { text: "ٱلَّذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ", tafsir: `` },
            { text: "فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ", tafsir: `` },
            { text: "وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ", tafsir: `« إمّا » مركّبة من « إن » الشرطية و « ما » الزائدة ، تأتي ( 1) مجمع البيان : ج 4 ص 483. مِنْ قَوْمٍ خِيانَةً فَانْبِذْ إِلَيْهِمْ عَلى سَواءٍ إِنَّ اللهَ لا يُحِبُّ الْخائِنِينَ (58) للتوسع في معنى الشرط ، يعني : ولو كان الاحتمال ضعيفا ، إن لم تدخل نون التأكيد ، وإلّا أفادت التأكيد في الشرط ، بأن يكون الاحتمال قويا ( مِنْ قَوْمٍ خِيانَةً ) أي إن خفت يا رسول الله من قوم من هؤلاء المعاهدين خيانة ، بأن يخونوا عهدك ويحاربوك فجأة بعد إبرام الميثاق ( فَانْبِذْ إِلَيْهِمْ عَلى سَواءٍ ) أي ألق المعاهدة بينك وبينهم ، إلقاء منتهيا إليهم ، بمعنى أعلمهم عن إلقاءك للعهد ، حتى يكون كلا الطرفين على سواء في الأمر ، لا أن يكونوا هم بصدد المباغتة وأنتم في أمن ودعة منهم ، فإن الإنسان إذا علم أن خصمه في عهد يأمن ، أما إذا علم أنه في حرب يستعد ، أما أن يبقى متزلزلا يخاف خيانته ، فإنه في اضطراب وارتباك ، والعهد في نظر العرف ليس مما إذا أبرم دام ، بل معلق بنقضه من الطرفين مع الاعلام ( إِنَّ اللهَ لا يُحِبُّ الْخائِنِينَ ) أي فلا تخنهم يا رسول الله بالقتال فجأة بدون إعلام ، بل أعلمهم النقض ثم إذا أردت قتالهم ، فقاتلهم بعد الاعلام. وعن بعض المفسرين : إن الآية نزلت في بني قينقاع من اليهود ، فإنه كان بين النبي وبين أولئك معاهدة ، وحيث أن اليهود كان من طبعهم الخيانة خاف الرسول صلى‌الله‌عليه‌وآله‌وسلم ذلك ، ولذا حلّ العهد الذي بينهم ، لئلّا يباغتوه وهو صلى‌الله‌عليه‌وآله‌وسلم في أمن منهم. ثم صارت بينهم المحاربة (1) . [60] إن الكفار بنقضهم العهد دون الاعلام ، وخيانتهم وغدرهم ـ كما صدر ( 1) مجمع البيان : ج 4 ص 485 ، عن الواقدي. وَلا يَحْسَبَنَّ الَّذِينَ كَفَرُوا سَبَقُوا إِنَّهُمْ لا يُعْجِزُونَ (59) وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِباطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللهِ وَعَدُوَّكُمْ وَآخَرِينَ مِنْ دُونِهِمْ لا تَعْلَمُونَهُمُ من بني قريظة ـ يظنون أنهم قد سبقوا ، وأدركوا فرصة ذهبية سببت عجز المسلمين ، لكنه ليس كذلك ( وَلا يَحْسَبَنَ ) يا رسول الله ( الَّذِينَ كَفَرُوا ) بنقضهم العهد وغدرهم ( سَبَقُوا ) واستفادوا من فرصة المباغتة والسبق ( إِنَّهُمْ لا يُعْجِزُونَ ) أي أن هؤلاء الكفار لا يعجزون المسلمين ، بمعنى أنهم بغدرهم لا يسببون عجز المسلمين ، بل الله سبحانه ناصرهم ، فإن الله سبحانه في عون الوفيّ لا الغادر ، ولذا ذهب بنو قريظة أدراج خيانتهم ، بينما غلبهم المسلمون.` },
            { text: "وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ إِنَّهُمْ لَا يُعْجِزُونَ", tafsir: `` },
            { text: "وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ", tafsir: `أيها المسلمون ، والإعداد هو التهيئة قبل وقوع الأمر ( لَهُمْ ) أي للكفار ( مَا اسْتَطَعْتُمْ ) ما قدرتم عليه ( مِنْ قُوَّةٍ ) دفاعية وهجومية ، بتهيئة وسائل الحرب ، حتى تكونوا دائمي الاستعداد ، سواء هاجمتم أو هوجمتم. ولعل إطلاق القوة يشمل جميع أنحاء القوى المادية والمعنوية وغيرها ( وَ ) ما استطعتم ( مِنْ رِباطِ الْخَيْلِ ) أي ربط الخيل واقتناءها للجهاد والحرب ( تُرْهِبُونَ بِهِ ) أي تخوّفون بسبب إعداد ما استطعتم ( عَدُوَّ اللهِ وَعَدُوَّكُمْ ) فإن الكافر عدو الله لمخالفته له ، وعدو المسلمين كما هو واضح. ولعل المراد بهم : أهل مكة ، فإنهم كانوا ظاهري العداوة ( وَآخَرِينَ مِنْ دُونِهِمْ ) أي ترهبون به كفارا آخرين دون أولئك في العداوة ، أي أن عداوتهم أضعف ، أو دون أولئك في المحل كبني قريظة الذين كانوا قريبين من المدينة ( لا تَعْلَمُونَهُمُ ) أي لا تعلمون أيها المسلمون أنهم أعداء لكم اللهُ يَعْلَمُهُمْ وَما تُنْفِقُوا مِنْ شَيْءٍ فِي سَبِيلِ اللهِ يُوَفَّ إِلَيْكُمْ وَأَنْتُمْ لا تُظْلَمُونَ (60) وَإِنْ جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَها وَتَوَكَّلْ عَلَى اللهِ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ (61) وَإِنْ يُرِيدُوا أَنْ يَخْدَعُوكَ ( اللهُ يَعْلَمُهُمْ ) حيث يعلم ما بطن من الأمور. وهذا درس للمسلمين بأن يستعدوا لأي عدو لئلّا يباغتوا ( وَما تُنْفِقُوا مِنْ شَيْءٍ فِي سَبِيلِ اللهِ ) فإن الحرب تحتاج إلى الإنفاق ، ولذا يقرن غالبا الجهاد بالإنفاق في الآيات الكريمة ( يُوَفَّ إِلَيْكُمْ ) أي يرجع إليكم في الدنيا بالغنيمة وشبهها ، وفي الآخرة بالثواب الجزيل ( وَأَنْتُمْ لا تُظْلَمُونَ ) لا يظلمكم الله تعالى بأن يعطيكم أقل مما أخذ منكم.` },
            { text: "وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `الجنوح : الميل ، ومنه جناح الطائر لأنه يميل به في أحد طرفيه ، أي إن مال الكفار ( لِلسَّلْمِ ) وعدم الحرب ( فَاجْنَحْ لَها ) أي مل إليها واقبلها منهم ، و « السلم » مؤنث سماعي ، ولذا جيء بالضمير مؤنثا ( وَتَوَكَّلْ عَلَى اللهِ ) أي فوّض أمرك إليه ، فلا تخف أن تفوتك الفرصة ، فإن السلم أحرى أن تلين القلوب فيه ويكفي مؤونة أتعاب الحرب ( إِنَّهُ ) سبحانه ( هُوَ السَّمِيعُ ) لأقوال الطرفين ( الْعَلِيمُ ) بنياتهم ، فلا يفوته غدر غادر وسلم مسالم. ومن المعلوم أن الجنوح للسلم إذا كان من مصلحة المسلمين فلا ينسخ قوله : ( قاتِلُوا الْمُشْرِكِينَ ) (1) ، هذه الآية ، بل كلّ في مقام المصلحة.` },
            { text: "وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ", tafsir: `أولئك الذين يجنحون للسلم ( أَنْ يَخْدَعُوكَ ) بأن ( 1) التوبة : 36. فَإِنَّ حَسْبَكَ اللهُ هُوَ الَّذِي أَيَّدَكَ بِنَصْرِهِ وَبِالْمُؤْمِنِينَ (62) وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنْفَقْتَ ما فِي الْأَرْضِ جَمِيعاً ما أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلكِنَّ اللهَ أَلَّفَ بَيْنَهُمْ إِنَّهُ عَزِيزٌ حَكِيمٌ (63) يا أَيُّهَا النَّبِيُّ حَسْبُكَ اللهُ وَمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ (64) يجدوا فرصة لتهيئة العدّة للغدر بك وقتالك ( فَإِنَّ حَسْبَكَ اللهُ ) هو يكفيك شرهم ، ويتولى أمورك ، فإنه كما كفاك سابقا يكفيك الآن ( هُوَ الَّذِي أَيَّدَكَ ) أي قوّاك ( بِنَصْرِهِ ) أي النصرة التي أنزلها عليك ( وَبِالْمُؤْمِنِينَ ) أي أيدك بالمؤمنين الذين التفوا حولك ، فتمكنت أن تبارز بهم الأعداء.` },
            { text: "وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُۥ عَزِيزٌ حَكِيمٌ", tafsir: `المتنافرة حتى يكونوا قوة واحدة في وجه الأعداء ، فإن وحدة الكلمة من أهم أسباب النصر ، وقد كانوا قبل الإسلام في أشد حالة من العداوة والبغضاء حتى أنه كان بين الأوس والخزرج عداوة وقتال دام أكثر من مائة سنة ( لَوْ أَنْفَقْتَ ما فِي الْأَرْضِ جَمِيعاً ما أَلَّفْتَ بَيْنَ قُلُوبِهِمْ ) فإن المال يزيد العداوة ، فإنه يكون وقودا لها ، وإنما أزال الله سبحانه الضغائن بتصفية القلوب وتطهير أدران النفوس ( وَلكِنَّ اللهَ أَلَّفَ بَيْنَهُمْ ) بهدايتهم للإسلام المطهّر للعداوة عن الأفئدة ( إِنَّهُ ) سبحانه ( عَزِيزٌ ) غالب على أمره ، فإذا أراد شيئا أوجده ( حَكِيمٌ ) بحكمته وتدبيره يدبّر الأمور ويديرها.` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ", tafsir: `أي يكفيك في مقابلة الأعداء ( وَمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ ) فإنهم كافون بالنسبة إلى القوى الظاهرة ، وهذا تشجيع يا أَيُّهَا النَّبِيُّ حَرِّضِ الْمُؤْمِنِينَ عَلَى الْقِتالِ إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صابِرُونَ يَغْلِبُوا مِائَتَيْنِ وَإِنْ يَكُنْ مِنْكُمْ مِائَةٌ يَغْلِبُوا أَلْفاً مِنَ الَّذِينَ كَفَرُوا بِأَنَّهُمْ قَوْمٌ لا يَفْقَهُونَ (65) للرسول صلى‌الله‌عليه‌وآله‌وسلم لئلّا ينظر إلى كثرة الأعداء ، كما جرت العادة في الحروب العادية. قال بعض المفسرين : نزلت في البيداء قبل الشروع في القتال في وقعة بدر (1) .` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ إِن يَكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ", tafsir: `أي رغّب ( الْمُؤْمِنِينَ عَلَى الْقِتالِ ) بذكر فوائده وآثاره وأنهم يسودون بسببه ويحوزون الأجر والثواب في الآخرة لأجله ( إِنْ يَكُنْ مِنْكُمْ ) أيها المؤمنون ( عِشْرُونَ صابِرُونَ ) على القتال ( يَغْلِبُوا مِائَتَيْنِ ) من الكفار فكل واحد من المؤمنين في قبال عشرة من الكافرين ( وَإِنْ يَكُنْ مِنْكُمْ مِائَةٌ يَغْلِبُوا أَلْفاً مِنَ الَّذِينَ كَفَرُوا ) وذلك لأن الإيمان والتضحية طاقتان عظيمتان تبدّلان الإنسان العادي إلى شخص شجاع مقدام ، وذلك الضعف في الكفار بسبب أنهم ( قَوْمٌ لا يَفْقَهُونَ ) أي لا يفهمون ، فمن يحارب عن معرفة وإيمان يزوّد بما لا يزوّد به الإنسان الخليّ من العقيدة والدين ، وإن من عرف أنه إن قتل دخل الجنة وإن قتل دخل الجنة ، كان قوي القلب في مقابل من لا يفقه ذلك. [67] إن الفئة إذا كانت قليلة كانت الطاقة الإيمانية فيها قوية جدا ، وذلك لأنها تتقوّى حتى تتمكن من مقابلة القوي ، وهذا أمر بيّن في علم ( 1) مجمع البيان : ج 4 ص 490 ، عن الكلبي. الْآنَ خَفَّفَ اللهُ عَنْكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفاً فَإِنْ يَكُنْ مِنْكُمْ مِائَةٌ صابِرَةٌ يَغْلِبُوا مِائَتَيْنِ وَإِنْ يَكُنْ مِنْكُمْ أَلْفٌ يَغْلِبُوا أَلْفَيْنِ بِإِذْنِ اللهِ وَاللهُ مَعَ الصَّابِرِينَ (66) النفس ، فالنفس القوية تأتي بما تحير العقول فيه ، إما إذا كثرت الفئة فإن روح الاتكالية تقوى فيهم ، وبمقدار ارتفاع نسبة الاتكالية ، تنخفض القوة والطاقة ، ولذا نرى الأمم أول تكوّنها أنشط منها في أواسط حياتها ، فكيف بأواخرها ، وهذا هو السبب في أن خفّف الله الحكم عن المؤمنين بعد أن كثروا ، ( الْآنَ ) وبعد أن كثرتم أيها المؤمنون ( خَفَّفَ اللهُ عَنْكُمْ ) في لزوم مقابلة الواحد منكم لعشرة من الكفار ( وَعَلِمَ ) الله ( أَنَّ فِيكُمْ ضَعْفاً ) عطف على « الآن » لا على « خفف » والمراد بالضعف : ضعف الطاقة ، لا ضعف الجسد ( فَإِنْ يَكُنْ مِنْكُمْ ) أيها المسلمون ( مِائَةٌ صابِرَةٌ ) تصبر على المكاره ( يَغْلِبُوا مِائَتَيْنِ ) من الكفار ( وَإِنْ يَكُنْ مِنْكُمْ أَلْفٌ ) صابرين ( يَغْلِبُوا أَلْفَيْنِ ) من الكفار ( بِإِذْنِ اللهِ ) وإرادته حيث أراد لكم أن تكونوا أقوى من عدوكم بما وهب لكم من الإيمان ، فإن الرجل منكم يعادل رجلين من العدو ، فإنه وإن كان أضعف من الحكم السابق ولكنه أيضا بإذنه سبحانه ( وَاللهُ مَعَ الصَّابِرِينَ ) ينصرهم ويعينهم. ولعل الحكمين تابعان لحالة نفوس المسلمين في كل دور ، فمتى رأوا قوة من أنفسهم كان العشرة منهم بمائة ، ومتى رأوا الضعف من أنفسهم كان العشرة منهم بعشرين ، فلا نسخ في البين ، والله العالم. [68] أسر المسلمون يوم بدر سبعين أسيرا فقتل النبي صلى‌الله‌عليه‌وآله‌وسلم منهم ثلاثة ، وخاف ما كانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرى حَتَّى يُثْخِنَ فِي الْأَرْضِ تُرِيدُونَ عَرَضَ الدُّنْيا وَاللهُ يُرِيدُ الْآخِرَةَ وَاللهُ عَزِيزٌ حَكِيمٌ (67) المسلمون أن يقتلهم جميعا فتقدموا إلى النبي صلى‌الله‌عليه‌وآله‌وسلم بأخذ الفداء منهم رغبة في المال ، وقد كان النبي صلى‌الله‌عليه‌وآله‌وسلم يعلم أن قتل بعضهم أصلح ، كما كان كذلك شأن الأنبياء قبله ، وذلك لأن رؤوس المؤامرات إذا أطلقوا عاثوا في الأرض فسادا وعادوا إلى المجتمع بأكثر قتلا وفتكا ، لكن النبي صلى‌الله‌عليه‌وآله‌وسلم قبل طلب هؤلاء لأمر أصلح وهو أن لا يختلف أصحابه بما يعود بأكثر ضررا ، فنزلت هذه الآية توبيخا للمسلمين : ( ما كانَ لِنَبِيٍ ) أي ليس له ، ولم يكن في عهد الله إليه ( أَنْ يَكُونَ لَهُ أَسْرى ) بأن يأخذ الأسير ثم يطلقه منّا ، أو في مقابل الفدية ( حَتَّى يُثْخِنَ فِي الْأَرْضِ ) الإثخان : التغليظ ، أي يحمل الأرض ثقلا بالقتلى ، أو المعنى : حتى يغلب في الأرض ليخاف الكفار سطوته ، فإنهم إن علموا أنهم إن وقعوا أسرى فدّوا وتحرروا ، جرّأهم ذلك على الاستمرار في المؤامرة والمكايدة ، لكنهم إن عرفوا أن وراءهم القتل ، قلت جرأتهم ، وسلمت الدولة من شرهم. فهل ( تُرِيدُونَ ) أيها المسلمون ( عَرَضَ الدُّنْيا ) أي المصالح الدنيوية ، وسمي عرضا لأنه لا يبقى ، والمراد به هنا : المال المأخوذ فدية ( وَاللهُ يُرِيدُ الْآخِرَةَ ) فإنكم إن صرفتم النظر عن المال لأجل ثواب الله سبحانه ، كان خيرا لكم ( وَاللهُ عَزِيزٌ ) ذو قوة ومنعة ، فاعملوا بأوامره حتى يقويكم ( حَكِيمٌ ) يدبر الأمور بحكمته البالغة ، فما يأمر به هو المصلحة دون ما تظنون. لَوْ لا كِتابٌ مِنَ اللهِ سَبَقَ لَمَسَّكُمْ فِيما أَخَذْتُمْ عَذابٌ عَظِيمٌ (68) فَكُلُوا مِمَّا غَنِمْتُمْ حَلالاً طَيِّباً وَاتَّقُوا اللهَ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (69)` },
            { text: "ٱلْـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ", tafsir: `` },
            { text: "مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْـَٔاخِرَةَ وَٱللَّهُ عَزِيزٌ حَكِيمٌ", tafsir: `` },
            { text: "لَّوْلَا كِتَٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ", tafsir: `أي لو لا أن الله سبحانه كتب سابقا أن لا يعذب الناس حتى يبيّن لهم ، كما قال سبحانه : ( وَما كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً ) (1) ، ( لَمَسَّكُمْ ) أيها المسلمون ( فِيما أَخَذْتُمْ ) من الفدية ( عَذابٌ عَظِيمٌ ) . إن النبي صلى‌الله‌عليه‌وآله‌وسلم لم يكن عليه غضاضة لأنه لاحظ الأصلح من توحيد كلمة أصحابه حيث قبل أخذ الفدية مكرها ، أما المسلمون فقد استحقوا العقوبة حيث رجّحوا المال على ما فيه خيرهم ورغبة نبيهم صلى‌الله‌عليه‌وآله‌وسلم . و قد ورد في الحديث : أن الفدية كانت أربعين أوقية من الفضة ، كل أوقية أربعين مثقالا ، إلّا العباس عم النبي صلى‌الله‌عليه‌وآله‌وسلم حيث أخذ منه مائة أوقية (2) . [70] أما إذا انتهى الأمر وأخذتم الفدية فلا بأس في أكلكم لها ( فَكُلُوا مِمَّا غَنِمْتُمْ ) من الكفار ( حَلالاً طَيِّباً ) والطيب إذا قورن بالحلال أفاد معنى عدم نفرة الطبع منه في مقابل الحلال الذي ينفر منه الطبع ( وَاتَّقُوا اللهَ ) فلا تخالفوا أوامره ( إِنَّ اللهَ غَفُورٌ ) قد غفر ذنبكم في أخذكم الفدية ( رَحِيمٌ ) يرحمكم فيما بعد بلطفه ، مقابل بعض الكبار الذين إذا غفر ذنب المذنب ، ينتهي الأمر عند ذلك ، فلا يرحمه بعد ذلك. ( 1) الإسراء : 16. ( 2) عوالي اللآلي : ج 2 ص 101. يا أَيُّهَا النَّبِيُّ قُلْ لِمَنْ فِي أَيْدِيكُمْ مِنَ الْأَسْرى إِنْ يَعْلَمِ اللهُ فِي قُلُوبِكُمْ خَيْراً يُؤْتِكُمْ خَيْراً مِمَّا أُخِذَ مِنْكُمْ وَيَغْفِرْ لَكُمْ وَاللهُ غَفُورٌ رَحِيمٌ (70) وَإِنْ يُرِيدُوا خِيانَتَكَ فَقَدْ خانُوا اللهَ مِنْ قَبْلُ فَأَمْكَنَ مِنْهُمْ` },
            { text: "فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ", tafsir: `أي تحت استيلائكم ، وذكر « اليد » لأنها تكون الآخذة للأشياء غالبا ( مِنَ الْأَسْرى ) جمع أسير ، والمراد بهم أسرى بدر الذين أسرهم المسلمون ( إِنْ يَعْلَمِ اللهُ فِي قُلُوبِكُمْ خَيْراً ) بأن لم تكن قلوبكم محشوة بالحقد والعداوة بل طاهرة نظيفة ( يُؤْتِكُمْ ) أي يعطيكم ( خَيْراً مِمَّا أُخِذَ مِنْكُمْ ) من الفداء ، وإنما يعطيكم ذلك لطفا ورحمة لا استحقاقا وعوضا ( وَيَغْفِرْ لَكُمْ ) ذنوبكم. ومن المعلوم أن ذلك مشروط بالإيمان ( وَاللهُ غَفُورٌ رَحِيمٌ ) وقد كان العباس بن عبد المطلب يقول : نزلت هذه الآية فيّ وفي أصحابي ، كان معي عشرون أوقية ذهبا فأخذت مني فأعطاني الله مكانها عشرين عبدا كل منهم يضرب بمال كثير وأدناهم يضرب بعشرين ألف درهم مكان العشرين أوقية. [72] ثم سلّى الله سبحانه نبيّه حول إطلاق الأسرى بالفداء نزولا عند رغبة أصحابه ، بأنه لا يهمّه ما لعل الطلقاء يقومون به من مؤامرة جديدة ضده ( وَإِنْ يُرِيدُوا ) أي يريد الطلقاء ( خِيانَتَكَ ) بأن يكون في نيّتهم تجديد المؤامرة ( فَقَدْ خانُوا اللهَ مِنْ قَبْلُ ) في قصة خروجهم إلى بدر ( فَأَمْكَنَ ) الله المسلمين ( مِنْهُمْ ) فقتلوهم وأسروهم ، والله قادر على أن يمكّن المسلمين منهم ثانية إن خافوا منهم. وسمى خروجهم إلى وَاللهُ عَلِيمٌ حَكِيمٌ (71) إِنَّ الَّذِينَ آمَنُوا وَهاجَرُوا وَجاهَدُوا بِأَمْوالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللهِ وَالَّذِينَ آوَوْا وَنَصَرُوا أُولئِكَ بَعْضُهُمْ أَوْلِياءُ بَعْضٍ وَالَّذِينَ آمَنُوا وَلَمْ يُهاجِرُوا بدر خيانة باعتبار وجوب شكر المنعم ، لا باعتبار سبق معاهدة ، فإنك إذا أنعمت وتفضلت على أحد ، ثم قام ضدك يقال : أنه خانك ( وَاللهُ عَلِيمٌ ) بإرادتهم الخيانة وعدمها ( حَكِيمٌ ) يدير الأمور حسب الحكمة ، فهم في قبضة علمه وإرادته لا يتمكنون من الإضرار بك. [73] وبمناسبة ذكر الحرب وعلاقة المسلمين بالمشركين ، يأتي ذكر علاقة المسلمين بعضهم ببعض ، وأنها علاقة الإيمان والعقيدة والهجرة ( إِنَّ الَّذِينَ آمَنُوا ) بالله ورسوله وبما جاء به الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَهاجَرُوا ) من مكة إلى المدينة ( وَجاهَدُوا ) أي حاربوا الكفار ( بِأَمْوالِهِمْ ) بأن بذلوها في سبيل الجهاد ( وَأَنْفُسِهِمْ فِي سَبِيلِ اللهِ ) ويأتي ذكر « سبيل الله » في كل مناسبة للتنبيه على أن حركة المسلمين ليست إلا لإعلاء كلمة الله ( وَالَّذِينَ آوَوْا ) أي الأنصار من أهل المدينة الذين جعلوا للرسول والمهاجرين مأوى بأن أسكنوهم في منازلهم ، فإن المهاجرين لم يكن لهم مسكنا حين وردوا المدينة فأسكنهم الأنصار معهم في بيوتهم ( وَنَصَرُوا ) أي نصروا الرسول والمهاجرين على أعدائهم ( أُولئِكَ بَعْضُهُمْ أَوْلِياءُ بَعْضٍ ) وليست هنالك ولاية بين المسلم وقريبه الكافر ، والولاية كلمة عامة تشمل أقسام الولاية والنصرة. ( وَالَّذِينَ آمَنُوا وَلَمْ يُهاجِرُوا ) إلى المدينة ، بل بقوا في مكة ما لَكُمْ مِنْ وَلايَتِهِمْ مِنْ شَيْءٍ حَتَّى يُهاجِرُوا وَإِنِ اسْتَنْصَرُوكُمْ فِي الدِّينِ فَعَلَيْكُمُ النَّصْرُ إِلاَّ عَلى قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ مِيثاقٌ وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ (72) وَالَّذِينَ كَفَرُوا بَعْضُهُمْ أَوْلِياءُ بَعْضٍ اختيارا ( ما لَكُمْ ) أي ليس لكم أيها المسلمون ( مِنْ وَلايَتِهِمْ مِنْ شَيْءٍ ) لأنهم خالفوا أمر الرسول وأضعفوا ـ ببقائهم في مكة ـ كيان المسلمين ( حَتَّى يُهاجِرُوا ) كما هاجرتم ( وَإِنِ اسْتَنْصَرُوكُمْ فِي الدِّينِ ) أي طلب المؤمنون غير المهاجرين منكم أيها المهاجرون أن تنصروهم على أعدائهم الكفار ، في الأمور الدينية ( فَعَلَيْكُمُ النَّصْرُ ) ومن المعلوم أن النصرة غير الولاية المطلقة ، لأن المسلمين في المدينة كان ينصر بعضهم بعضا ، ويسكن أحدهم الآخر في داره ، ويجتمعون في السلم والحرب ، وأخذ الغنائم ، ويتفقد أحدهم الآخر ، كأهل بيت واحد ، بخلاف النصر المجرّد على الكافر الذي قرّره سبحانه للمسلمين في مكة. ( إِلَّا عَلى قَوْمٍ بَيْنَكُمْ ) أيها المسلمون المهاجرون ( وَبَيْنَهُمْ مِيثاقٌ ) فإذا استنصركم المسلمون في مكة على كفار معاهدين معكم ، فلا تخرقوا المعاهدة ، ولا تنصروا المسلمين ، لأن المسلم لا يغدر بعهده ، ولا ينقض ميثاقه وإن كان مع الكافر ( وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ ) فلا تتركوا موالاة المهاجرين ، ولا تتولوا غير المهاجرين.` },
            { text: "وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `` },
            { text: "وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ", tafsir: `ليسوا لكم بأولياء وإن كانوا أقرباؤكم بالنسب أو باللغة أو بالوطن بل ( بَعْضُهُمْ أَوْلِياءُ بَعْضٍ ) ينصر بعضهم بعضا إِلاَّ تَفْعَلُوهُ تَكُنْ فِتْنَةٌ فِي الْأَرْضِ وَفَسادٌ كَبِيرٌ (73) وَالَّذِينَ آمَنُوا وَهاجَرُوا وَجاهَدُوا فِي سَبِيلِ اللهِ وَالَّذِينَ آوَوْا وَنَصَرُوا أُولئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ (74) وَالَّذِينَ آمَنُوا مِنْ بَعْدُ وَهاجَرُوا ضدكم وإن اختلفوا. وبهذا المعنى ورد : « الكفر كله ملة واحدة » ( إِلَّا تَفْعَلُوهُ ) أي إن لم تفعلوا ما أمرتم به من ولاية المؤمنين ، واعتبار الكفار كلهم ملّة واحدة ، بأن عاديتم المؤمنين أو واليتم الكافرين ( تَكُنْ فِتْنَةٌ فِي الْأَرْضِ وَفَسادٌ كَبِيرٌ ) لأن في ذلك تعزيزا للكفر وإذلالا للإسلام ، وقد دلّ منطق التاريخ أن كل وقت اتخذ فيه المسلمون الكافرين أولياء ، ضعفت شوكتهم وذهبت ريحهم ، وبالعكس كل وقت اتخذوهم فيه أعداء ، واتخذوا سائر المسلمين أولياء ، قويت شوكتهم وهبت ريحهم.` },
            { text: "وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ", tafsir: `من مكة إلى المدينة ( وَجاهَدُوا فِي سَبِيلِ اللهِ ) لإعلاء كلمته وتطبيق حكمه ( وَالَّذِينَ آوَوْا وَنَصَرُوا ) من أهل المدينة الذين أعطوا المسلمين مأوى ونصروهم على أعدائهم ( أُولئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا ) لقيامهم بجميع شرائط الإيمان ( لَهُمْ مَغْفِرَةٌ ) من الله لذنوبهم ( وَرِزْقٌ كَرِيمٌ ) أي مع الكرامة في الدنيا وفي الآخرة ، فإن المؤمنين إذا ما عملوا بشرائط الإيمان تمّت عليهم بركات من السماء والأرض.` },
            { text: "وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ مَعَكُمْ فَأُو۟لَٰٓئِكَ مِنكُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ", tafsir: `` }
        ]
    }
});
